INSERT INTO new_exams (exam_no, tag_code, display_order, config_id, name_ar, name_en, description_ar, description_en, question_count) VALUES
  (0, 'full', 1, 1, 'اختبار PMP Core أكتوبر 2026 (1)', 'PMP Core October 2026 (1)', 'امتحان كامل من 180 سؤالًا يغطي مجالات PMP الثلاثة، بمدة 4 ساعات واستراحتين.', '180 questions across the three PMP domains, timed at 4 hours with two scheduled breaks.', 180),
  (1, 'full', 2, 1, 'اختبار PMP Core أكتوبر 2026 (2)', 'PMP Core October 2026 (2)', 'امتحان كامل من 176 سؤالًا يغطي مجالات PMP الثلاثة، بمدة 4 ساعات واستراحتين.', '176 questions across the three PMP domains, timed at 4 hours with two scheduled breaks.', 176),
  (2, 'full', 3, 1, 'اختبار PMP Core أكتوبر 2026 (3)', 'PMP Core October 2026 (3)', 'امتحان كامل من 180 سؤالًا يغطي مجالات PMP الثلاثة، بمدة 4 ساعات واستراحتين.', '180 questions across the three PMP domains, timed at 4 hours with two scheduled breaks.', 180);
INSERT INTO new_questions (exam_no, question_index, text_ar, text_en, explanation_ar, explanation_en, answer_count) VALUES
  (0, 0, 'تقود مديرة مشروع مبادرة للتحول الرقمي في إحدى البلديات، بميزانية قدرها 8 ملايين دولار أمريكي ومدة مخططة تبلغ 20 شهرًا. يهدف المشروع إلى تطوير منصة موحدة تتيح للمواطنين تقديم طلبات التراخيص، ودفع الرسوم، ومتابعة المعاملات إلكترونيًا.
INSERT INTO new_questions (exam_no, question_index, text_ar, text_en, explanation_ar, explanation_en, answer_count) VALUES
  (1, 20, 'أنت مدير لمشروع مهم. مؤشر أداء الجدول الزمني هو 1.8 ومؤشر أداء التكلفة هو 0.1. أخبر راعي المشروع مدير المشروع أنه إذا استمر هذا الاتجاه. فسيضطر إلى إغلاق المشروع قبل الأوان. ماذا يجب أن يفعل مدير المشروع؟', 'You are managing a high-priority project. The schedule performance index (SPI) is 1.8 and the cost performance index (CPI) is 0.1. The project sponsor tells you that if this trend continues, the project will have to be terminated early. What should the project manager do?', 'مؤشر الجدول 1.8 يعني أن القيمة المكتسبة أعلى من المخطط عند نقطة القياس، بينما مؤشر التكلفة 0.1 يشير إلى كفاءة تكلفة شديدة الانخفاض. الخيار الأقرب هو إيقاف ضغط الجدول، خصوصًا إذا كانت إضافة الموارد لتسريع العمل سبب التجاوز المالي. لكن المؤشرين وحدهما لا يثبتان أن الضغط هو السبب؛ لذا يلزم التحقق من البيانات وتحليل أسباب التجاوز قبل اعتماد الإجراء.', 'An SPI of 1.8 means earned value is ahead of planned value at the status date, while a CPI of 0.1 indicates extremely poor cost efficiency. The closest option is to stop crashing the schedule, particularly if adding resources to accelerate the work is driving the cost overrun. However, these indices alone do not prove that schedule crashing caused the overrun, so the project manager should verify the data and analyze the causes before deciding on corrective action.', 1),
  (1, 21, 'اقترح فريق المشروع على مدير المشروع أنه لا توجد حاجة إلى تنفيذ ضبط الجودة؛ لأن مهام المشروع بسيطة جدًا. كما يرى مدير المشروع أن حذف خطة إدارة الجودة قد يساعد على توفير المال، وهو أمر مهم للعميل. ماذا ينبغي أن يفعل مدير المشروع؟', 'The project team tells the project manager that quality control is unnecessary because the project tasks are very simple. The project manager also believes that omitting the quality management plan could save money, which is important to the customer. What should the project manager do?', 'تُخطط الجودة وتُضبط حتى عندما تبدو المهام بسيطة؛ فبساطة العمل لا تلغي معايير القبول أو احتمال العيوب. يمكن تكييف مقدار الفحص والتوثيق حسب حجم المشروع ومخاطره، مع الحفاظ على المتطلبات اللازمة. حذف الخطة أو الاعتماد على خبرة شخص واحد قد يزيد إعادة العمل وتكاليف الفشل. والتدقيق بعد قبول المخرجات لا يعوض إدارة الجودة أثناء التنفيذ.', 'Quality should be planned and controlled even when tasks seem simple. Simplicity does not eliminate acceptance criteria or the possibility of defects. The amount of inspection and documentation can be tailored to the project’s size and risk while preserving required standards. Omitting the plan or relying on one person’s experience can increase rework and cost of failure. An audit after deliverable acceptance does not replace quality management during execution.', 1),
  (1, 22, 'تم إبلاغ مدير المشروع بأن إطلاق إصدار المنتج خلال 15 شهرًا غير مقبول، وأنه يجب إطلاق المنتج خلال ستة أشهر. بناءً على الجدول الزمني الجديد، ما الذي يجب على مدير المشروع فعله؟', 'The project manager is told that a product release in 15 months is unacceptable and that the product must be released in six months. Given the new schedule, what should the project manager do?', 'تقليص مدة الإطلاق من 15 شهرًا إلى ستة أشهر يستدعي مراجعة الأولويات وتحديد أصغر منتج يحقق قيمة قابلة للاختبار ضمن الوقت المتاح. يُتفق مع مالك المنتج والمعنيين على محتوى المنتج القابل للتطبيق، ثم تُخطط الإضافات التالية. مضاعفة الموارد أو فرض العمل الإضافي لا يضمن اختصار المدة بهذا القدر، وقد يرفع التكلفة والمخاطر.', 'Reducing the release timeline from 15 months to six requires reprioritizing the work and defining the smallest product that can deliver testable value within the available time. The project manager should align with the product owner and stakeholders on the MVP, then plan subsequent enhancements. Tripling resources or imposing overtime does not guarantee this degree of schedule reduction and may increase cost and risk.', 1),
  (1, 23, 'تم تحديد عيب أثناء اختبار قبول المستخدم يمكن أن يؤثر بشكل كبير على أداء النظام. أوضح فريق المشروع أن هذا العيب يعرض تاريخ التسليم للخطر. ما عملية إدارة المخاطر التي يجب القيام بها؟', 'A defect identified during user acceptance testing could significantly affect system performance. The project team says that the defect puts the delivery date at risk. Which risk management process should be performed?', 'التحليل النوعي يقيّم احتمال المخاطر وأثرها وأولويتها، ومن ثم يحدد أهمية تهديد العيب لموعد التسليم والأداء. وهو الأنسب بين الخيارات لتقييم الأثر قبل اختيار استجابة تفصيلية. وبما أن العيب اكتُشف بالفعل، فهو مشكلة قائمة تُسجَّل وتُعالج أيضًا؛ أما آثاره المستقبلية غير المؤكدة فتدار كمخاطر. التحليل الكمي ليس مطلوبًا تلقائيًا لكل عيب.', 'Qualitative risk analysis assesses probability, impact, and priority to determine how seriously the defect threatens the delivery date and system performance. Among the options, it is the best process for assessing impact before selecting a detailed response. Because the defect has already been identified, it is also an issue that should be recorded and addressed; uncertain future effects can be managed as risks. Quantitative analysis is not automatically required for every defect.', 1),
  (1, 24, 'تستورد المنظمة العديد من المواد لبناء منتج. بسبب تأخيرات الشحن العالمية، لم تصل بعد بعض المواد الأساسية، مما أدى إلى عدم القدرة على إنهاء بناء المنتج للإصدار القادم. يجتمع مدير المشروع مع المعنيين لمناقشة الخيارات. ماذا يجب أن يوصي مدير المشروع؟', 'An organization imports many materials to build a product. Because of global shipping delays, some essential materials have not arrived, preventing completion of the product build for the next release. The project manager meets with stakeholders to discuss options. What should the project manager recommend?', 'الشراء المحلي قد يوفر مصدرًا بديلًا يقلل الاعتماد على الشحن المتأخر ويساعد على حماية موعد الإصدار. يجب التحقق من مطابقة المواد للمواصفات والجودة والتكلفة وشروط التعاقد قبل اعتماد البديل. التصنيع الداخلي قد يستلزم وقتًا واستثمارًا أكبر، بينما تعديل الإجازات أو تسويق منتج قائم لا يحل مباشرة نقص المواد الأساسية المطلوبة للمنتج.', 'Local sourcing may provide an alternative supply and reduce dependence on delayed shipments, helping protect the release date. Before approving the alternative, the project manager should verify that the materials meet specification, quality, cost, and contractual requirements. In-house manufacturing may require more time and investment, while changing holidays or marketing an existing product does not directly resolve the shortage of materials needed for this product.', 1),
  (1, 25, 'تم تعيين مدير مشروع لمشروع ميزانيته ضيقة للغاية. ولا يمكن تكبد تكاليف إضافية. ما الذي يجب أن يفعله مدير المشروع لإدارة هذا الوضع؟', 'A project manager is assigned to a project with an extremely tight budget, and no additional costs can be incurred. What should the project manager do to manage this situation?', 'الميزانية المقيدة تحتاج إلى متابعة مستمرة للتكاليف والالتزامات والتوقعات عند الإكمال، حتى تظهر الانحرافات قبل أن تتحول إلى تجاوز فعلي. يناقش مدير المشروع البدائل والإجراءات التصحيحية ضمن صلاحياته، ويطلب الموافقات عند الحاجة. مطالبة الفريق بالعمل أسرع دون تحليل لا تضمن خفض التكلفة، كما أن نقل المصروفات إلى البريد الإلكتروني لا يعد رقابة مالية كافية.', 'A constrained budget requires continuous monitoring of costs, commitments, and the estimate at completion so variances can be identified before they become actual overruns. The project manager should discuss alternatives and corrective actions within their authority and obtain approvals when needed. Asking the team to work faster without analysis does not ensure lower costs, and routing expenses to an email account is not adequate financial control.', 1),
  (1, 26, 'تمت دعوة مالك المنتج إلى اجتماع مراجعة التكرار.. وفي نهاية المراجعة. صرّح مالك المنتج بأن الزيادة أصبحت جاهزة للتسليم إلى العميل. ما الاستنتاج الذي ينبغي على مدير المشروع التوصل إليه بشأن تصريح مالك المنتج؟', 'The product owner is invited to an iteration review. At the end of the review, the product owner states that the increment is ready for delivery to the customer. What should the project manager infer from this statement?', 'تعبير مالك المنتج عن جاهزية الزيادة للتسليم يفترض تحقق تعريف الإنجاز ومعايير القبول ذات الصلة. يحدد تعريف الإنجاز مستوى الجودة الذي يجب أن تبلغه الزيادة. في سكرم يتحمل المطورون مسؤولية الالتزام بهذا التعريف، ويقرر مالك المنتج توقيت الإصدار بحسب القيمة؛ لذلك لا يعني التصريح أن مالك المنتج وحده يختبر الجودة أو أن كل مراجعة تؤدي حتمًا إلى إطلاق فوري.', 'The product owner’s statement that the increment is ready for delivery implies that the Definition of Done and relevant acceptance criteria have been met. The Definition of Done establishes the quality level the increment must achieve. In Scrum, developers are accountable for adhering to it, while the product owner decides when to release based on value. The statement does not mean the product owner alone tested quality or that every review results in an immediate release.', 1),
  (1, 27, 'تم تفويض مدير المشروع لبدء أحد المشاريع. وأدرك أن نجاح المشروع وإكماله يتطلبان تكوين فريق فعال وعالي الأداء. ما الذي ينبغي على مدير المشروع فعله بعد ذلك؟', 'A project manager is authorized to initiate a project and recognizes that successful completion requires building an effective, high-performing team. What should the project manager do next?', 'يتطلب بناء فريق مناسب معرفة ما سيقدمه المشروع وما النتائج التي يجب أن يحققها الفريق. توضيح النطاق والأهداف يحدد المهارات والأدوار اللازمة، ويوفر غرضًا مشتركًا يمكن قياس الأداء عليه. بعد ذلك تُختار الموارد وتُتفق توقعات العمل والاجتماعات. اختيار الأعضاء أو وضع معايير الأداء قبل فهم المهمة قد ينتج فريقًا غير ملائم لاحتياجات المشروع.', 'Building the right team requires understanding what the project will deliver and what outcomes the team must achieve. Clarifying the scope and objectives identifies the skills and roles needed and provides a shared purpose against which performance can be assessed. The project manager can then select resources and agree on working and meeting expectations. Selecting team members or setting performance criteria before understanding the work may result in a team that does not meet the project’s needs.', 1),
  (1, 28, 'يشعر راعي المشروع بالقلق من أن نطاق المشروع لا يتم تنفيذه بصورة صحيحة، وقد وجّه أسئلة إلى عدة أعضاء من الفريق بصورة فردية حول هذا الموضوع. عندما تحدث الراعي مع مدير المشروع، أدرك مدير المشروع أن المشكلة تتمثل في أن الراعي يفهم النطاق بطريقة مختلفة عن فهم الفريق له. ما الذي ينبغي على مدير المشروع فعله لمعالجة هذه المشكلة؟', 'The project sponsor is concerned that the project scope is not being performed correctly and has asked several team members about it individually. During a discussion with the project manager, the manager realizes that the sponsor understands the scope differently from the team. What should the project manager do to address this issue?', 'تحتاج اختلافات فهم النطاق إلى حوار مشترك يوضح المخرجات ومعايير القبول وما تم اعتماده. يجمع مدير المشروع الراعي والفريق للوصول إلى فهم واحد، ويوثق الاتفاق. إذا كشف الحوار طلب تغيير فعليًا، يُحلل ويُعتمد عبر الإجراء المناسب. لا يغيّر الفريق المخرجات لمجرد اختلاف التفسير، ولا تكفي متابعة الاجتماعات اليومية لمعالجة غموض النطاق.', 'Different interpretations of scope call for a joint discussion to clarify deliverables, acceptance criteria, and what has been approved. The project manager should bring the sponsor and team together, reach a shared understanding, and document the agreement. If the discussion reveals an actual change request, it should be analyzed and approved through the appropriate process. The team should not change deliverables based only on a difference in interpretation, and daily status meetings will not resolve scope ambiguity.', 1),
  (1, 29, 'يطلب الرئيس التنفيذي لشركة مقاولات عامة بصورة عاجلة من مدير المشروع تسجيل عضوين من الفريق للمشاركة في دورة تدريبية محددة. في منتصف التدريب، يشتكي العضوان من أن التدريب صعب جدًا وفوق مستوى خبرتهما، وأن المواد لا تتوافق مع مهامهما. ما الذي كان يجب على مدير المشروع فعله لمنع هذا الوضع؟', 'The chief executive officer of a general contracting company urgently asks the project manager to enroll two team members in a specific training course. Halfway through the course, the team members complain that it is too advanced for their experience and that the material is not relevant to their tasks. What should the project manager have done to prevent this situation?', 'يجب تقييم كفاءات الأعضاء واحتياجات مهامهم ومحتوى التدريب ومستواه قبل ترشيحهم. تسمح هذه المقارنة باختيار تدريب مناسب يسد فجوة محددة ويمكن تطبيقه في العمل. طلب المدير التنفيذي لا يلغي ضرورة التحقق من الملاءمة وتوضيح البدائل له. استبدال الأعضاء أو إضافة دورة لاحقة بعد اكتشاف عدم مناسبة التدريب يزيد التكلفة دون منع المشكلة الأصلية.', 'The project manager should assess team members’ competencies, task needs, and the course content and level before nominating them. Comparing these factors helps select training that addresses a specific gap and can be applied at work. A request from the CEO does not remove the need to verify suitability and explain alternatives. Replacing team members or adding a follow-up course after discovering the mismatch increases cost without preventing the original problem.', 1),
  (1, 30, 'تم تشكيل فريق لمشروع جديد سيستخدم النهج التنبؤي خلال جمع المتطلبات، ونهج أجايل خلال التطوير والاختبار. لكن ليس جميع أعضاء الفريق لديهم خبرة في العمل باستخدام أجايل. بدأ الجدول الزمني في التأخر بسبب عدم وضوح هيكل وطريقة العمل في جزء التطوير باستخدام أجايل. ما الذي كان يجب على مدير المشروع فعله لتجنب هذا الموقف؟', 'A team is formed for a new project that will use a predictive approach for requirements gathering and an agile approach for development and testing. However, not all team members have experience working with agile. The schedule begins to slip because the team is unclear about the structure and way of working during the agile development portion. What should the project manager have done to avoid this situation?', 'النهج الهجين يحتاج إلى اتفاق واضح مع الفريق على طريقة العمل واتخاذ القرار والأهداف في الجزء الرشيق. مشاركة الأعضاء في وضع هذه الترتيبات تدعم التنظيم الذاتي وتمنع ارتباك المسؤوليات، ولذلك يعد الخيار الرابع الأنسب بين البدائل. ومع نقص الخبرة ينبغي أيضًا توفير التدريب والتوجيه المناسبين. تقارير الحالة أو تصعيد التأخير لا تعوّض إعداد الفريق مسبقًا.', 'A hybrid approach requires the team to agree on how it will work, make decisions, and set goals for the agile portion. Involving members in these arrangements supports self-management and prevents confusion about responsibilities, making option D the best choice among the alternatives. Given the experience gap, appropriate training and coaching should also be provided. Status reports or delay escalation do not replace preparing the team in advance.', 1),
  (1, 31, 'اكتشف فريق يعمل وفق المنهجيات الرشيقة أنه لا يستطيع تنفيذ إحدى الخصائص بالكامل خلال التكرار الأول، ويعتقد أنه قد لا يتمكن من إكمالها حتى خلال التكرار الثاني. وتعد هذه الخاصية من أهم الخصائص التي منحها العميل أولوية عالية. ماذا يجب أن يفعل الفريق؟', 'An agile team realizes that it cannot complete a feature in the first iteration and believes that it may not be able to complete it in the second iteration either. The customer has assigned a high priority to this feature. What should the team do?', 'تُقسَّم الخاصية الكبيرة إلى أجزاء أصغر قابلة للتنفيذ والتحقق، بحيث يقدم كل جزء قيمة واضحة ويحافظ مجموعها على الهدف المطلوب. يسمح ذلك بتسليم تدريجي عبر عدة تكرارات والحصول على ملاحظات مبكرة. لا تُحذف وظائف مهمة أو يُبسّط مطلب العميل من طرف واحد، ويُنسق التقسيم والأولوية ومعايير القبول مع مالك المنتج.', 'A large feature should be divided into smaller, implementable, and verifiable parts so that each part provides clear value and the collection of parts still achieves the intended outcome. This enables incremental delivery over several iterations and earlier feedback. The team should not remove important functionality or simplify the customer’s requirement unilaterally. The decomposition, priority, and acceptance criteria should be coordinated with the product owner.', 1),
  (1, 32, 'مدير مشروع يقود مشروعًا في مرحلة متقدمة. تم حل جميع المخاطر عالية المستوى المحددة ولم تعد تشكل خطرًا على المشروع. تبقى فقط المخاطر المنخفضة المستوى ماذا يجب أن يفعل مدير المشروع الآن؟', 'A project manager is leading a project that is in an advanced phase. All identified high-level risks have been resolved and no longer threaten the project. Only low-level risks remain. What should the project manager do now?', 'إدارة المخاطر تستمر طوال المشروع. بعد إغلاق المخاطر العالية يُعاد تقييم المخاطر المتبقية والتحقق من فعالية الاستجابات وظهور مخاطر جديدة أو ثانوية، ثم يُحدّث السجل. قد يتغير مستوى خطر منخفض مع تغير الظروف، لكنه لا يُرفع تلقائيًا دون تحليل. إبلاغ المعنيين مفيد، إلا أنه لا يغني عن إعادة التقييم والمتابعة المستمرة.', 'Risk management continues throughout the project. After high-level risks are closed, the remaining risks should be reassessed, response effectiveness checked, and any new or secondary risks identified and recorded. A low-level risk may change as conditions change, but it should not be raised automatically without analysis. Informing stakeholders is useful, but does not replace reassessment and ongoing monitoring.', 1),
  (1, 33, 'يعمل مدير المشروع على مشروع لتطوير برنامج لصالح عميل في قطاع النفط والغاز باستخدام نهج أجايل. يواجه مدير المشروع صعوبة في إعداد الجدول الزمني؛ لأن المشروع يحتوي على العديد من الأمور غير المعروفة. ما طريقة الجدولة التي يجب على مدير المشروع استخدامها لإعداد الجدول الزمني؟', 'A project manager is leading an agile software development project for a client in the oil and gas industry. The project manager is having difficulty creating a schedule because the project contains many unknowns. Which scheduling method should the project manager use?', 'الجدولة التكرارية تناسب المشاريع التي تتطور متطلباتها مع التعلم. يُخطط العمل القريب بتفصيل أكبر، وتُراجع التقديرات والأولويات في كل تكرار بحسب النتائج والملاحظات والقدرة الفعلية للفريق. طرق التقدير الأخرى قد تدعم هذه العملية، لكنها لا تمثل وحدها طريقة جدولة تستوعب كثرة الأمور غير المعروفة وتغيرها خلال المشروع.', 'Iterative scheduling is suitable for projects whose requirements evolve through learning. Near-term work is planned in greater detail, and estimates and priorities are revisited during each iteration based on results, feedback, and the team’s actual capacity. Other estimating techniques may support the process, but they do not by themselves provide a scheduling method that accommodates numerous unknowns and changes over the course of the project.', 1),
  (1, 34, 'تُنفذ شركة مقاولات عقدًا لإنشاء مبنى، ويتضمن العقد أحداثًا رئيسية ثابتة لاستبدال بعض مكونات المبنى. أثناء التنفيذ، اشتكى العميل من أن المكونات الجديدة لا تطابق المتطلبات. ماذا كان ينبغي أن يفعل مدير المشروع لمنع حدوث هذه المشكلة؟', 'A construction company is executing a contract to build a building. The contract includes fixed milestones for replacing some building components. During execution, the customer complains that the new components do not meet the requirements. What should the project manager have done to prevent this problem?', 'الاتفاق المسبق على معايير قبول قابلة للتحقق وربطها بقائمة فحص للجودة يوضح المواصفات المطلوبة لكل مكون قبل البناء. يستخدم الفريق هذه المعايير أثناء التنفيذ والفحص، فيكشف عدم المطابقة قبل تسليمها للعميل. التواصل وضبط التغيير مهمان، لكنهما لا يعوضان غياب معيار متفق عليه يمكن مقارنة المخرجات به.', 'Agreeing in advance on verifiable acceptance criteria and linking them to a quality checklist clarifies the required specifications for each component before construction. The team can use the criteria during execution and inspection to detect nonconformance before delivery to the customer. Communication and change control are important, but they do not replace an agreed standard against which the deliverables can be assessed.', 1),
  (1, 35, 'تنتقل إحدى المؤسسات إلى أسلوب التسليم باستخدام أجايل، وتم تشكيل فريق جديد. لا يسير أحد المشاريع بصورة جيدة؛ لأن سرعة إنجاز الفريق تتغير بدرجة كبيرة. وفي كل سبرنت ينجز الفريق عملًا أقل من العمل الذي التزم به. تم تعيين قائد مشروع جديد لديه خلفية فنية قوية لإدارة المشروع. ما الذي يجب على قائد المشروع فعله؟', 'An organization is transitioning to agile delivery and has formed a new team. A project is not going well because the team’s velocity varies significantly. In every sprint, the team completes less work than it committed to. A new project lead with a strong technical background is assigned to the project. What should the project lead do?', 'تكرار المبالغة في الالتزام وتذبذب السرعة يشير إلى حاجة الفريق لفحص طريقة التقدير والتخطيط في الاجتماع الاستعادي. يمكن تجربة تقدير جماعي نسبي واستخدام بيانات الإنجاز الفعلي لتحسين التوقعات، ثم تقييم النتيجة. لا يفرض القائد الفني تقديراته ولا يحصرها في ذوي الخبرة؛ كما أن زيادة وقت التقدير وحدها لا تصلح طريقة غير مناسبة.', 'Repeated overcommitment and variable velocity indicate that the team should inspect its estimation and planning approach during the retrospective. It can try collaborative relative estimation and use actual delivery data to improve forecasts, then evaluate the results. The technically experienced lead should not impose estimates or restrict them to experienced members. Simply extending estimation time will not fix an unsuitable method.', 1),
  (1, 36, 'تم تعيين مدير مشروع مؤخرًا لإنقاذ مشروع ذي أولوية مرتفعة لإنشاء منشأة أولمبية. المشروع متأخر عن الجدول الزمني، ويوجد شرط جزائي تعاقدي كبير بسبب التأخير. وكان مدير المشروع السابق لديه خلافات عديدة مع أعضاء الفريق وبعض المعنيين. ما الذي يجب على مدير المشروع فعله أولًا؟', 'A project manager is recently assigned to rescue a high-priority project to build an Olympic facility. The project is behind schedule and subject to a substantial contractual penalty for delay. The previous project manager had many disagreements with team members and stakeholders. What should the project manager do first?', 'الخطوة الأولى هي فهم أسباب التأخير والخلافات بمشاركة الفريق والمعنيين، ثم الاتفاق على حل عملي. قد يكون السبب تبعيات أو موارد أو تواصلًا أو توقعات غير متسقة. لا يبرر ضغط الموعد فرض السلطة أو ضغط الجدول فورًا دون تحليل. مراجعة الدروس السابقة تفيد التحقيق، لكنها لا تغني عن سماع الأطراف وفهم الوضع الحالي.', 'The first step is to understand the causes of the delay and disagreements with input from the team and stakeholders, then agree on a practical solution. Causes may include dependencies, resources, communication, or misaligned expectations. The urgency does not justify asserting authority or compressing the schedule before analysis. Reviewing lessons learned may support the investigation, but does not replace hearing from the people involved and understanding the current situation.', 1),
  (1, 37, 'أبلغ المورد مدير المشروع بأنه سيكون هناك نقص قادم في المواد الخام بسبب تغيير تنظيمي. ماذا يجب أن يفعل مدير المشروع؟', 'A supplier informs the project manager that a shortage of raw materials is expected because of a regulatory change. What should the project manager do?', 'يبدأ مدير المشروع بتقييم أثر نقص المواد المتوقع في المخرجات والجدول والتكلفة والجودة، وتحديد مدى إلحاحه. بعد فهم الأثر يمكن اختيار مورد بديل أو تعديل خطة التوريد أو تطبيق استجابة معتمدة. إلزام المورد أو فرض عقوبات لا يحل تلقائيًا أثر تغيير تنظيمي، والبحث عن بديل قبل معرفة الاحتياجات قد يؤدي إلى قرار غير مناسب.', 'The project manager should first assess how the expected shortage may affect deliverables, schedule, cost, and quality, and determine its urgency. Once the impact is understood, the project manager can select an alternative supplier, adjust the supply plan, or implement an approved response. Requiring the supplier to deliver or imposing penalties does not automatically resolve the effect of a regulatory change. Seeking an alternative before understanding the need may lead to an unsuitable decision.', 1),
  (1, 38, 'أعاد العميل عدة مكونات من مشروع تصنيع مرتفع التكلفة. ويشتكي العميل من انخفاض جودة هذه المكونات. ويشعر بالقلق من أن منتجاته قد يتم إرجاعها بسبب مشكلات الجودة. ومع ذلك. فإن مدير المشروع متأكد من الحفاظ على الجودة المطلوبة. كيف ينبغي أن يتواصل مدير المشروع مع العميل ليطمئنه إلى أن المشروع قد أنتج منتجات ذات جودة؟', 'A customer returns several components from a high-cost manufacturing project, complaining that their quality is poor and expressing concern that the customer’s own products may be returned because of quality problems. The project manager is confident that the required quality has been maintained. How should the project manager communicate with the customer to provide assurance that quality products have been produced?', 'قياسات ضبط الجودة تقدم نتائج فعلية للفحص والاختبار يمكن مقارنتها بمتطلبات المنتج وحدود القبول المتفق عليها. وهي أقوى دليل بين الخيارات لتوضيح مستوى المطابقة. مع ذلك يجب التحقيق في المكونات المرتجعة وأسباب الشكوى ومشاركة النتائج والإجراء التصحيحي؛ فوجود قياسات جيدة لا يبرر رفض ملاحظات العميل أو افتراض خلو جميع المنتجات من العيوب.', 'Quality control measurements provide actual inspection and test results that can be compared with product requirements and agreed acceptance limits. Among the options, they are the strongest evidence of conformance. The project manager should also investigate the returned components and complaint, and share findings and corrective actions. Good measurements do not justify dismissing the customer’s feedback or assuming that every product is defect-free.', 1),
  (1, 39, 'بدأ مدير المشروع للتو في قيادة فريق بعد استقالة المدير السابق. بعد إجراء تقييم سريع، اتضح أن الروح المعنوية للفريق منخفضة بسبب الخلافات المستمرة حول كيفية تنفيذ المهام، وأن المهام تستغرق وقتًا أطول من المتوقع، وأصبح المشروع متأخرًا عن الجدول الزمني. ما الذي يجب على مدير المشروع فعله؟', 'A project manager has just taken over a team after the previous manager resigned. A quick assessment shows low team morale because of ongoing disagreements about how to perform tasks. Tasks are taking longer than expected, and the project is behind schedule. What should the project manager do?', 'الخلافات المستمرة تستهلك وقت التنفيذ وتخفض المعنويات، ولذلك تُعالج أسبابها مباشرة في نقاش ييسره مدير المشروع. يُتفق على طريقة العمل والمسؤوليات وآلية حل الخلافات، ثم تتابع النتائج. ضغط الجدول أو تمديده قبل معالجة السبب قد يضيف تكلفة أو وقتًا دون تحسين الأداء، وإلقاء اللوم على المدير السابق لا يساعد الفريق على التقدم.', 'Ongoing disagreements consume delivery time and reduce morale, so the project manager should address their causes directly through a facilitated discussion. The team can agree on how to work, responsibilities, and a way to resolve disagreements, then monitor the results. Crashing or extending the schedule before addressing the cause may add cost or time without improving performance. Blaming the previous manager does not help the team move forward.', 1),
  (1, 40, 'طُلب من مدير المشروع المشاركة في عملية شراء تطبيق برمجي يسمح للعملاء بشراء دورات تدريبية عبر الإنترنت. سيتولى مدير المشروع إدارة المشروع بمجرد تحديد المورد. ماذا يجب أن يفعل قبل أن يبدأ المشروع؟', 'A project manager is asked to participate in procuring a software application that allows customers to purchase training courses online. The project manager will manage the project once a supplier has been selected. What should the project manager do before the project starts?', 'يجب أن تعكس الاتفاقية المتطلبات والأهداف ومعايير القبول والالتزامات بوضوح قبل اعتمادها. مشاركة مدير المشروع مبكرًا تساعد على تجنب عقد لا يدعم ما سيُطلب منه تنفيذه لاحقًا. يمكن إشراك المختصين القانونيين والمشتريات بحسب الصلاحيات، لكن ذلك لا يلغي مسؤوليته عن فهم المشروع. ويمكن تعديل النطاق بعد التوقيع عبر إجراءات تغيير تعاقدية معتمدة.', 'Before approval, the agreement should clearly reflect the requirements, objectives, acceptance criteria, and commitments. Early project manager participation helps prevent an agreement that does not support the work the manager will later be expected to deliver. Legal and procurement specialists can be involved according to their authority, but this does not remove the project manager’s responsibility to understand the project. Scope can be changed after signing through approved contractual change procedures.', 1),
  (1, 41, 'علم مدير مشروع جديد أن العمل المسند إلى الفريق قد تم تقسيمه بالفعل إلى أدنى مستوى له. راجع مدير المشروع العمل. لكنه شعر بأن بعض المعلومات الإضافية والمفيدة غير موجودة. ما الوثيقة التي ينبغي على مدير المشروع مراجعتها؟', 'A new project manager learns that the work assigned to the team has already been decomposed to its lowest level. The project manager reviews the work but feels that some useful additional information is missing. Which document should the project manager review?', 'يوضح قاموس هيكل تجزئة العمل التفاصيل المرتبطة بحزم العمل، مثل الوصف والمخرجات والمسؤوليات والافتراضات ومعايير القبول. عندما يكون العمل مقسمًا بالفعل وتكون المشكلة نقص معلومات عن أجزائه، يكون القاموس هو المرجع المباشر. خطة النطاق تشرح كيفية إدارته، ومصفوفة التتبع تربط المتطلبات بمصادرها ومخرجاتها، ولا تحلان محل تفاصيل حزم العمل.', 'The WBS dictionary provides details about work packages, such as descriptions, deliverables, responsibilities, assumptions, and acceptance criteria. When the work has already been decomposed and the missing information concerns its components, the dictionary is the direct reference. The scope management plan explains how scope is managed, while the requirements traceability matrix links requirements to their sources and deliverables; neither replaces work package details.', 1),
  (1, 42, 'تم الانتهاء من سجل المنتج وترتيب أولوياته، وبدأ السبرنت الأول. خلال اجتماع الوقوف اليومي، أبلغ أحد أعضاء الفريق عن وجود تأخير في توقيع عقد مع مورد خارجي. ما أولوية مدير المشروع في هذه الحالة؟', 'The product backlog has been completed and prioritized, and the first sprint has started. During the daily standup, a team member reports a delay in signing a contract with an external supplier. What is the project manager’s priority in this situation?', 'تأخر توقيع العقد عائق قد يمنع الفريق من تحقيق هدف السبرنت. يساعد القائد الخادم على كشف سبب التأخير وتنسيق إزالته مع المشتريات والأطراف المخولة، ومتابعة الإجراء. لا يلزم أن يتولى التفاوض بنفسه أو يطلب من العضو حل الأمر منفردًا. وتُراجع الخيارات مع الفريق إذا تعذر إزالة العائق في الوقت المناسب.', 'The delayed contract is an impediment that may prevent the team from achieving the sprint goal. The servant leader should identify the cause of the delay, coordinate its removal with procurement and authorized parties, and follow up on the action. The project manager does not necessarily need to take over negotiations or ask the team member to resolve the matter alone. If the impediment cannot be removed in time, options should be reviewed with the team.', 1),
  (1, 43, 'تم تعيين مدير مشروع ليعمل كقائد خادم في مشروع قائم كان يعاني تاريخيًا من مشكلات غير متوقعة. يشعر أحد المعنيين الرئيسيين بالتردد في الاستمرار في بقية السبرنتات. على الرغم من عدم وجود أي مشكلات مفتوحة أو مؤشرات لمخاطر في هذه المرحلة. ما الذي يجب على مدير المشروع فعله لمعالجة هذه المشكلة؟', 'A project manager is assigned to serve as a servant leader on an existing project that has historically experienced unexpected problems. A key stakeholder is hesitant to continue with the remaining sprints, even though there are no open issues or risk indicators at this stage. What should the project manager do to address this concern?', 'دورات الفحص والملاحظات القصيرة توفر للمعني دليلًا متكررًا على التقدم والجودة والمخاطر، وتتيح معالجة القلق قبل أن تتفاقم المشكلة. يعزز ذلك الشفافية والثقة في مشروع سبق أن عانى مفاجآت. زيادة الاحتياطيات دون تحليل لا تبني الثقة بذاتها، ولا يصح تصنيف المعني كعائق لمجرد تردده. كما أن الاحتياطي الإداري والطارئ لهما استخدامات وصلاحيات محددة.', 'Short inspection and feedback cycles give the stakeholder recurring evidence about progress, quality, and risks, allowing concerns to be addressed before they escalate. This supports transparency and builds confidence in a project that has experienced surprises. Increasing reserves without analysis does not by itself build confidence, and a stakeholder should not be labeled an impediment solely for being hesitant. Management and contingency reserves also have defined uses and authorization rules.', 1),
  (1, 44, 'يشرف مدير المشروع على مشروع ترقية مدرج مطار، حيث تم التعاقد مع مورد خارجي لتركيب أضواء المدرج. يتأخر تركيب الأضواء بصورة ملحوظة عن الجدول الزمني، ويقع الانتهاء من المدرج على المسار الحرج. ما الذي يجب على مدير المشروع فعله أولًا؟', 'A project manager is overseeing an airport runway upgrade project. An external supplier has been contracted to install runway lights. Installation is significantly behind schedule, and runway completion is on the critical path. What should the project manager do first?', 'العمل مع المورد لتحليل سبب التأخر وتحديد بدائل قابلة للتنفيذ هو البداية المناسبة، خصوصًا لأن النشاط يؤثر في المسار الحرج. تُراجع قدرته والتزاماته والتبعيات، وتُقدّر آثار أي خطة استرداد. استبدال المورد أو إضافة موارد قبل معرفة السبب قد يزيد التأخير والتكلفة، ويُصعّد الأمر عندما تحتاج الاستجابة إلى صلاحية أو قرار يتجاوز مدير المشروع.', 'The appropriate first step is to work with the supplier to analyze the cause of the delay and identify feasible alternatives, especially because the activity affects the critical path. The project manager should review the supplier’s capacity, commitments, and dependencies and assess any recovery plan. Replacing the supplier or adding resources before understanding the cause may increase delay and cost. Escalation is appropriate when a response requires authority or a decision beyond the project manager’s remit.', 1),
  (1, 45, 'أثناء اجتماع الوقوف اليومي المخصص لتقييم التقدم في السبرنت الحالي، أبلغ أحد أعضاء الفريق عن وجود تأخيرات بسبب مكون يديره مورد خارجي. كيف يجب على مدير المشروع معالجة قلق عضو الفريق؟', 'During a daily standup to assess progress in the current sprint, a team member reports delays caused by a component managed by an external supplier. How should the project manager address the team member’s concern?', 'يحتاج مدير المشروع إلى تفاصيل التبعية والتأخير والأثر حتى يتواصل مع المورد ويزيل العائق بصورة مناسبة. طلب هذه المعلومات من العضو يحول القلق العام إلى إجراء محدد يمكن متابعته. التسريع دون تحليل قد يضيف مخاطر، وتعديل خطة التواصل لا يعالج المكون المتأخر مباشرة. ويمكن استكمال النقاش خارج الاجتماع اليومي حتى يبقى الاجتماع مركزًا على تنسيق العمل.', 'The project manager needs details about the dependency, delay, and impact to engage the supplier and remove the impediment appropriately. Asking the team member for this information turns a general concern into a specific, trackable action. Fast tracking without analysis may add risk, and changing the communications management plan does not directly resolve the delayed component. The discussion can continue outside the standup so the meeting remains focused on coordinating work.', 1),
  (1, 46, 'وصل مشروع متعدد المراحل، تم تنفيذه بموارد داخلية، إلى بوابة المرحلة. يرغب المعنيون الرئيسيون في تحديد ما إذا كانت المرحلة قد استوفت معايير النجاح الخاصة بها، وما إذا كان ينبغي للمشروع التقدم إلى المرحلة التالية. بالإضافة إلى خطة إدارة المشروع، ما المستندات المطلوبة؟', 'An internally resourced, multistage project has reached a phase gate. Key stakeholders want to determine whether the phase met its success criteria and whether the project should proceed to the next phase. In addition to the project management plan, which documents are needed?', 'تستخدم بوابة المرحلة وثائق الأعمال، ومنها دراسة الجدوى وخطة إدارة المنافع، للتحقق من استمرار قيمة المشروع ومبرر الاستثمار. ويبين الميثاق الأهداف ومعايير النجاح والتفويض، بينما تعرض خطة إدارة المشروع طريقة التنفيذ والقياس. تساعد هذه المراجع مع نتائج المرحلة الفعلية على قرار الاستمرار أو التعديل أو الإيقاف. سجلات المخاطر والدروس تدعم القرار، لكنها ليست بديلًا عن المبرر والأهداف.', 'A phase gate uses business documents, including the business case and benefits management plan, to confirm that the project’s value and investment justification remain valid. The charter states the objectives, success criteria, and authorization, while the project management plan describes how the work will be delivered and measured. Together with actual phase results, these references support a decision to continue, adjust, or stop. Risk and lessons learned records inform the decision but do not replace the justification and objectives.', 1),
  (1, 47, 'تم تعيين مدير مشروع لقيادة مشروع عالمي يمتد عبر عدة دول وثقافات. في المراحل الأولى من التنفيذ، لاحظ أن أعضاء الفريق في إحدى المناطق يترددون في مشاركة أفكارهم أو التواصل بصورة مفتوحة مع زملائهم في المناطق الأخرى. أكد الراعي أن التعاون وتبادل المعرفة عنصران أساسيان لنجاح المشروع. ماذا يجب أن يفعل مدير المشروع لبناء الثقة بين الفرق؟', 'A project manager is appointed to lead a global project spanning several countries and cultures. Early in execution, the manager notices that team members in one region are reluctant to share ideas or communicate openly with colleagues in other regions. The sponsor confirms that collaboration and knowledge sharing are essential to project success. What should the project manager do to build trust across the teams?', 'يساعد التدريب على الوعي الثقافي أعضاء الفريق على فهم اختلاف أساليب التعبير والمشاركة واتخاذ القرار، وتجنب تفسير التحفظ على أنه عدم اهتمام. يبني المدير كذلك بيئة آمنة تسمح بمشاركة الأفكار باحترام. تدريب اللغة وحده لا يعالج كل الفروق الثقافية، وتقسيم المسؤوليات حسب الصور النمطية قد يعمق الانعزال بين المناطق بدلًا من بناء الثقة.', 'Cultural awareness training helps team members understand differences in communication, participation, and decision-making styles and avoid interpreting reticence as a lack of interest. The project manager should also create a psychologically safe environment where ideas can be shared respectfully. Language training alone does not address all cultural differences, and assigning work according to stereotypes may deepen regional isolation rather than build trust.', 1),
  (1, 48, 'خلال اجتماع الوقوف اليومي، اكتشف مدير المشروع أن أحد مطوري البرمجيات يواجه صعوبة في إكمال عمله بسبب نقص خبرته في اختبارات الأتمتة، مما قد يؤثر في تحقيق هدف السبرنت. ويوجد ضمن الفريق مهندس ضمان جودة يمتلك خبرة في اختبارات الأتمتة، لكنه منشغل حاليًا بإعداد عرض تقديمي للموظفين الجدد. ماذا يجب أن يفعل مدير المشروع لزيادة فرص تحقيق هدف السبرنت؟', 'During the daily standup, the project manager learns that a software developer is having difficulty completing work because of limited experience with automated testing, which may put the sprint goal at risk. The team includes a quality assurance engineer with automated testing expertise, but that person is currently preparing a presentation for new employees. What should the project manager do to increase the likelihood of achieving the sprint goal?', 'توجيه الدعم المتاح إلى العمل الذي يهدد هدف السبرنت يساعد الفريق على إزالة فجوة المهارة سريعًا. يمكن لمهندس ضمان الجودة مساعدة المطور أو العمل معه على الاختبارات، مع تنسيق أولوية العرض التقديمي داخل الفريق. تأجيل الاختبارات أو انتظار اكتمال العرض يبقي العائق قائمًا، بينما التدريب المطول الفوري قد لا يناسب الوقت المتبقي لتحقيق الهدف.', 'Directing available support to work that threatens the sprint goal helps the team close a skills gap quickly. The quality assurance engineer can assist or pair with the developer on the tests, while the team coordinates the priority of the presentation. Delaying the tests or waiting for the presentation to be completed leaves the impediment in place. Immediate, lengthy training may not fit the time remaining to achieve the goal.', 1),
  (1, 49, 'خلال الشهر الثاني من مشروع هجين لتطوير بوابة رقمية لخدمة العملاء. لاحظ مدير المشروع نمطا متكررًا يتمثل في أن مالك المنتج يتغيب كثيرًا عن جلسات تنقيح سجل المنتج. ويقدم ملاحظات غير واضحة حول المخرجات. كما لا يستجيب لاستفسارات الفريق. ونتيجة لذلك. أصبح فريق التطوير يواجه صعوبة في فهم الأولويات. وأصبحت القيمة التجارية المخطط تحقيقها معرضة للخطر. ماذا يجب أن يفعل مدير المشروع لمعالجة هذه المشكلة؟', 'During the second month of a hybrid project to develop a digital customer service portal, the project manager notices a recurring pattern: the product owner frequently misses backlog refinement sessions, provides unclear feedback on deliverables, and does not respond to team inquiries. As a result, the development team struggles to understand priorities and the planned business value is at risk. What should the project manager do to address this issue?', 'ضعف مشاركة مالك المنتج يستلزم مراجعة طريقة إشراكه وفهم سبب الغياب والتواصل معه بشأن دوره والأولويات والقيمة المطلوبة. تُحدّث استراتيجية المشاركة بالتعاون مع المعنيين وتُحدد ترتيبات واضحة للاستجابة وتنقيح السجل. زيادة الاجتماعات أو التركيز على التنفيذ الفني لا يعالجان غموض الأولويات. ويمكن التصعيد لاحقًا إذا لم تتحسن المشاركة وكانت المشكلة تتجاوز قدرة المدير على معالجتها.', 'The project manager should review how the product owner is engaged, understand the reason for the absences, and discuss the role, priorities, and expected value. The engagement strategy should be updated with stakeholders to establish clear arrangements for responsiveness and backlog refinement. More meetings or a focus on technical execution will not resolve unclear priorities. Escalation may be appropriate later if participation does not improve and the issue is beyond the project manager’s ability to address.', 1),
  (1, 50, 'خلال مشروع يضم تخصصات متعددة. علم مدير المشروع بوجود العديد من الخلافات المتعلقة بالتصميم بين أعضاء الفريق من تخصصات مختلفة. ماذا يجب أن يفعل مدير المشروع لضمان سير المشروع بسلاسة؟', 'During a multidisciplinary project, the project manager learns that team members from different disciplines have many design-related disagreements. What should the project manager do to keep the project moving smoothly?', 'الخلافات الفنية بين التخصصات تحتاج إلى نقاش مشترك حول المتطلبات والبدائل والتبعيات للوصول إلى حل يخدم المشروع ككل. ييسر المدير الحوار ويحافظ على احترام الخبرات ومعايير القرار. إبلاغ الراعي أو المديرين قد يصبح ضروريًا إذا تعذر الحل ضمن صلاحية الفريق، لكنه لا يستبدل محاولة التعاون المباشر. وحجز احتياطي مالي لا يحل الخلاف في التصميم.', 'Technical disagreements across disciplines require a joint discussion of requirements, alternatives, and dependencies to reach a solution that serves the project as a whole. The project manager facilitates the discussion while respecting expertise and decision criteria. Informing the sponsor or functional managers may be necessary if the team cannot resolve the issue within its authority, but it does not replace direct collaboration. Budget reserves do not resolve the design disagreement.', 1),
  (1, 51, 'تعمل إحدى شركات تصنيع السيارات على تطوير الجيل الجديد من سيارتها الكهربائية الرائدة. وخلال مرحلة التخطيط. تم الإعلان عن سياسات بيئية جديدة تتطلب تقارير أكثر صرامة بشأن الانبعاثات. وفي الوقت نفسه. أظهرت أبحاث السوق وجود طلب قوي من العملاء على زيادة مدى البطارية. ويرى الفريق الهندسي أن تنفيذ كلا التغييرين سيؤدي إلى تجاوز خط الأساس للتكلفة والجدول الزمني. بينما يؤكد راعي المشروع أن رؤية المنتج يجب أن تظل متوافقة مع الاستراتيجية واللوائح التنظيمية. ماذا يجب أن يفعل مدير المشروع؟ (اختر إجابتين)', 'An automotive company is developing the next generation of its flagship electric vehicle. During planning, new environmental policies are announced that require more rigorous emissions reporting. At the same time, market research shows strong customer demand for greater battery range. The engineering team believes that implementing both changes will exceed the cost and schedule baselines, while the project sponsor emphasizes that the product vision must remain aligned with strategy and regulatory requirements. What should the project manager do? (Choose two.)', 'يجب أولًا فهم أثر التغير التنظيمي واتجاه السوق في رؤية المشروع، ثم التحقق من احتياجات العملاء بملاحظات وبيانات فعلية. يميز ذلك الامتثال الملزم عن التحسينات الاختيارية ويعطي أساسًا لاقتراح التغييرات. بعد التحليل تُراجع التكلفة والجدول وتُرفع الطلبات المطلوبة للحوكمة. إعادة صياغة استراتيجية المؤسسة تتجاوز دور مدير المشروع، ولا يُعتمد توسيع النطاق قبل تقييمه.', 'The project manager should first understand how the regulatory change and market trend affect the project vision, then validate customer needs with feedback and evidence. This distinguishes mandatory compliance from optional enhancements and provides a basis for proposing changes. After the analysis, cost and schedule impacts can be reviewed and required change requests submitted for governance approval. Redefining organizational strategy is beyond the project manager’s role, and scope should not be expanded before assessment.', 2),
  (1, 52, 'تقوم شركة إنشاءات ببناء مجمع مكاتب جديد. ويتوقع راعي المشروع إنجاز المبنى ضمن ميزانية محدودة. وهو مستعد للتنازل عن بعض الخصائص لتحقيق وفرات في التكلفة. وفي المقابل. يتوقع مدير إدارة المرافق استخدام مواد عالية الجودة وتجهيزات متقدمة لضمان الاستدامة طويلة الأجل وسهولة الصيانة. ويجب على مدير المشروع تحقيق التوافق بين توقعات المعنيين. ماذا يجب أن يفعل مدير المشروع؟', 'A construction company is building a new office complex. The project sponsor expects the building to be completed within a tight budget and is willing to compromise on some features to achieve cost savings. In contrast, the facilities manager expects high-quality materials and advanced fixtures to support long-term sustainability and ease of maintenance. The project manager must align the stakeholders’ expectations. What should the project manager do?', 'يجمع المدير المعنيين لفهم ما يحتاجه كل طرف واستكشاف بدائل تحقق توازنًا مقبولًا بين تكلفة الإنشاء والجودة والاستدامة والصيانة. يمكن دعم النقاش بتحليل تكلفة دورة الحياة والأثر على الجدول. تحليل البدائل منفردًا لا يضمن اتفاق الأطراف، وإعطاء الأفضلية حسب النفوذ فقط قد يهمل احتياجًا مهمًا. كما أن إشراكهما في كل تفصيل دون آلية واضحة لا يحل التعارض.', 'The project manager should bring the stakeholders together to understand each party’s needs and explore alternatives that balance construction cost, quality, sustainability, and maintenance. A life-cycle cost and schedule impact analysis can support the discussion. An analysis conducted in isolation does not ensure stakeholder agreement, and prioritizing solely by influence may overlook an important need. Involving both stakeholders in every detail without a clear decision process will not resolve the conflict.', 1),
  (1, 53, 'تقوم إحدى المؤسسات بتنفيذ مشروعين متشابهين في الوقت نفسه. ويؤكد راعي المشروع على أهمية تجنب تكرار الأخطاء وتعظيم الكفاءة بين المشروعين. ويحتاج مدير المشروع إلى التأكد من أن الدروس المستفادة من أحد المشروعين يتم تطبيقها بشكل منهجي في المشروع الآخر من خلال آلية لنقل المعرفة. ماذا يجب أن يفعل مدير المشروع؟', 'An organization is running two similar projects at the same time. The project sponsor emphasizes avoiding repeated mistakes and maximizing efficiency across both projects. The project manager needs to ensure that lessons learned from one project are systematically applied to the other through a knowledge transfer mechanism. What should the project manager do?', 'جلسات مشاركة المعرفة تسمح للمعنيين بشرح خبراتهم وسياق القرارات والأخطاء التي قد لا تظهر في الوثائق. تُحوّل الدروس إلى معرفة قابلة للمشاركة وتُوزع على الفريقين، ثم تُكيّف وتُطبق في المشروع الآخر وتُتابع فائدتها. الاجتماعات غير الرسمية وحدها لا تضمن نقلًا منهجيًا، وإعادة استخدام استجابة أو نتيجة دون فهم سياقها قد تنقل خطأ غير مناسب للمشروع الثاني.', 'Knowledge-sharing sessions allow stakeholders to explain experience, decision context, and mistakes that may not appear in documents. Lessons can be converted into shareable knowledge and distributed to both teams, then tailored and applied to the other project and their usefulness monitored. Informal meetings alone do not ensure systematic transfer. Reusing a response or outcome without understanding its context may introduce an unsuitable practice into the second project.', 1),
  (1, 54, 'تم تعيين مدير مشروع لإدارة مشروع قائم يضم أعضاء فريق افتراضيين من دول مختلفة يعملون عن بُعد وفي مناطق زمنية متعددة. ولاحظ مدير المشروع أن أعضاء الفريق لا ينجزون أنشطة المشروع في الوقت المحدد. كما أنهم غير قادرين على تقديم المخرجات المتوقعة بسبب عدم انتظام التواصل بينهم. كيف يجب على مدير المشروع معالجة هذه المشكلة؟', 'A project manager is assigned to manage an existing project with virtual team members working remotely from different countries and time zones. The project manager notices that team members are not completing project activities on time and cannot produce the expected deliverables because communication among them is inconsistent. How should the project manager address this issue?', 'التواصل المباشر مع أعضاء الفريق يكشف العوائق الفعلية، مثل اختلاف المناطق الزمنية أو غموض التبعيات أو ضعف أدوات التعاون. بعدها يتفق المدير والفريق على ترتيبات تواصل وتسليم تناسب ظروفهم. نقل الجميع إلى مكتب واحد قد لا يكون ممكنًا، والتدريب على الوقت أو إعادة توزيع قائمة المخرجات لا يعالج المشكلة قبل معرفة سببها.', 'Direct communication with team members can reveal the actual impediments, such as time-zone differences, unclear dependencies, or ineffective collaboration tools. The project manager and team can then agree on communication and handoff arrangements that fit their circumstances. Moving everyone to one office may not be feasible, and time management training or redistributing the deliverables list does not address the issue before its cause is understood.', 1),
  (1, 55, 'يعمل مدير مشروع على مشروع داخلي. ولاحظ أن رؤية وأهداف مديري الإدارات الأخرى غير واضحة. وقد أدى ذلك إلى حدوث ارتباك وغموض داخل فريق المشروع. وأصبح من الصعب التمييز بين الطلبات الإضافية (Wishlist) والعناصر التي تقع ضمن نطاق المشروع. أي وثيقة يجب على مدير المشروع مراجعتها لتوضيح هذا الموقف؟', 'A project manager is working on an internal project and notices that the vision and objectives of other department managers are unclear. This has caused confusion within the project team, making it difficult to distinguish additional wish-list requests from items within the project scope. Which document should the project manager review to clarify the situation?', 'يبين ميثاق المشروع الغرض والأهداف والمتطلبات عالية المستوى وحدود المشروع الأولية، فيوفر مرجعًا لتوضيح ما يخدم التفويض المعتمد. يساعد المدير على التمييز بين الهدف الأساسي والطلبات الإضافية، ثم يرجع إلى بيان النطاق وخط الأساس للتفاصيل عند توفرهما. خطط التواصل والمشاركة وسجل المخاطر لا تحدد وحدها مبرر المشروع وأهدافه.', 'The project charter states the project’s purpose, objectives, high-level requirements, and initial boundaries, providing a reference for clarifying what supports the approved authorization. The project manager can use it to distinguish core objectives from additional requests, then refer to the scope statement and baselines for details when available. Communications and engagement plans and the risk register do not by themselves define the project’s justification and objectives.', 1),
  (1, 56, 'قامت إحدى الشركات بتعيين مدير مشروع لقيادة مشروع يعمل بالمنهجية التكيفية باستخدام التطوير التكراري. بعد عدة دورات تطوير، بدأ الفريق يشعر بالإحباط لأن العميل لا يشارك بفاعلية ولا يساعد في تحديد معايير القبول. بدأ هذا الضعف في المشاركة يؤثر في معنويات الفريق وجودة التسليم. ما السبب الجذري الأكثر احتمالًا لهذه المشكلة؟', 'An organization assigns a project manager to lead an adaptive project using iterative development. After several development cycles, the team becomes frustrated because the customer is not actively participating or helping define acceptance criteria. This lack of engagement is affecting team morale and delivery quality. What is the most likely root cause?', 'في التسليم التكيفي تتطلب صياغة معايير القبول والتحقق من القيمة مشاركة واضحة للعميل أو ممثله. ضعف هذه المشاركة يرجح أن الأدوار والمسؤوليات لم توضح بما يكفي، لذلك يُراجع الاتفاق مع المعنيين وطريقة إشراكهم. هذا هو التفسير الأقرب بين الخيارات، لكنه يحتاج إلى التحقق بالحوار؛ فلا يمكن الجزم بالسبب من غياب المشاركة وحده.', 'In adaptive delivery, defining acceptance criteria and validating value require clear participation from the customer or its representative. The lack of engagement suggests that roles and responsibilities may not have been sufficiently clarified, so the project manager should review stakeholder agreements and engagement arrangements. This is the closest explanation among the options, but it should be verified through discussion; lack of participation alone does not prove the cause.', 1),
  (1, 57, 'كان أحد المشاريع الاستراتيجية يسير جيدًا مع وجود بروتوكولات تواصل معتمدة. فجأة اتصل أحد المعنيين الرئيسيين، الذي كان يتلقى تحديثات منتظمة، ليشتكي من عدم وضوح تقدم المشروع. بعد التحقيق، اكتشف المدير أن المعني انتقل مؤخرًا إلى منصب جديد، وأصبح يحتاج إلى نوع مختلف من المعلومات وتكرار مختلف للتقارير مقارنة بما كان يحتاجه سابقًا. لا يزال باقي المعنيين راضين عن أسلوب التواصل الحالي، بينما يمنح المنصب الجديد هذا المعني تأثيرًا كبيرًا على قرارات تمويل المشروع. ما الذي يجب على مدير المشروع فعله لمعالجة الموقف بفاعلية؟', 'A strategic project is progressing well under approved communication protocols. One key stakeholder, who has been receiving regular updates, suddenly complains that project progress is unclear. The project manager learns that the stakeholder recently moved into a new role and now needs different information and reporting frequency. Other stakeholders remain satisfied with the current approach, while the new role gives this stakeholder significant influence over project funding decisions. What should the project manager do to address the situation effectively?', 'تغيير الدور الوظيفي قد يغير تأثير المعني واحتياجاته وتوقعاته، ولذلك يُعاد تحليل وضعه وأثر ذلك في التواصل والمشاركة. تُستخدم النتائج للتحقق من المعلومات والتواتر المطلوبين معه، ثم تحديث خطة التواصل حسب الحاجة. الاجتماع الفردي وتعديل الخطة خطوات مفيدة ضمن المعالجة، لكن التحليل يضمن مواءمة التعديل مع دوره الجديد وتأثيره في تمويل المشروع.', 'A change in role can change a stakeholder’s influence, needs, and expectations, so the project manager should reassess the stakeholder and the effect on communication and engagement. The results can be used to confirm the information and frequency required, then update the communications management plan as needed. A one-on-one meeting and a plan update are useful actions within the response, but analysis ensures the changes are aligned with the stakeholder’s new role and influence over funding.', 1),
  (1, 58, 'يجري تنفيذ مشروع مدته ستة أسابيع. وخلال الأيام الأولى من التنفيذ واجه الفريق عائقًا كبيرًا. وبعد أن تعاون مدير المشروع مع الفريق لحل المشكلة. اكتشفوا بشكل غير متوقع حلاً يسمح بإكمال المشروع خلال ثلاثة أسابيع فقط. ما الذي يجب على مدير المشروع أن يفعله بعد ذلك؟', 'A six-week project is under way. During the first few days of execution, the team encounters a major impediment. After the project manager collaborates with the team to resolve it, they unexpectedly discover a solution that could allow the project to be completed in only three weeks. What should the project manager do next?', 'تقليص مدة المشروع بصورة غير متوقعة يمثل فرصة تحتاج إلى تقييم فائدتها ومخاطرها وتأثيرها في الجودة والالتزامات. يتواصل المدير مع المعنيين لاتخاذ قرار واعٍ بشأن اعتماد الحل وتحديث الخطة وفق الصلاحيات. لا تُعاد الموارد أو تضاف مخرجات تلقائيًا قبل الاتفاق، ولا تُهمل الفرصة لمجرد اختلافها عن الجدول الأصلي.', 'An unexpected reduction in the project duration is an opportunity that should be assessed for its benefits, risks, and effects on quality and commitments. The project manager should engage stakeholders to make an informed decision about adopting the solution and updating the plan within the proper authority. Resources should not be reassigned or new deliverables added automatically before alignment, and the opportunity should not be ignored simply because it differs from the original schedule.', 1),
  (1, 59, 'أثناء تنفيذ برنامج لتقنية المعلومات في قطاع الرعاية الصحية يضم العديد من المعنيين. استقال مدير المشروع لدى العميل دون إعداد خطة لتسليم المسؤوليات. ونتيجة لذلك. توقفت عدة مجموعات من المعنيين عن تلقي تحديثات المشروع. وبدأت تظهر مؤشرات مبكرة على عدم توافق التوقعات. كما أكد مدير المشروع الداخلي أن سجل المعنيين وقنوات التواصل الحالية لم تعد صالحة. ماذا يجب أن يفعل مدير المشروع؟', 'During execution of a healthcare IT program with many stakeholders, the client’s project manager resigns without a handover plan. As a result, several stakeholder groups stop receiving project updates, early signs of misaligned expectations emerge, and the internal project manager confirms that the current stakeholder register and communication channels are no longer valid. What should the project manager do?', 'استقالة مسؤول التواصل تغيّر العلاقات والأدوار وقنوات وصول المعلومات، ولذلك يُحلل أثرها في المعنيين ويُحدّث سجلهم واستراتيجية التواصل وخطته. يحدد المدير بديلًا واضحًا لتوزيع المعلومات والتحقق من وصولها وفهمها. الرسائل المؤقتة أو الاجتماع الطارئ قد يساعدان، لكن الحل المستدام يحتاج إلى إعادة تنظيم التواصل وتوثيق المسؤوليات الجديدة.', 'The resignation of a communication contact changes relationships, roles, and information channels. The project manager should analyze the impact on stakeholders and update the stakeholder register, communication strategy, and plan. A clear alternative should be established for distributing information and confirming that it is received and understood. Temporary emails or an emergency meeting may help, but a sustainable solution requires reorganizing communication and documenting the new responsibilities.', 1),
  (1, 60, 'يعمل فريق على مشروع لنشر تقنية جديدة. ولم يتم تنفيذ هذا المنتج من قبل. لذلك لا توجد بيانات تاريخية أو سجلات لمشروعات سابقة يمكن الاستفادة منها. ويُطلب من الفريق تقديم جدول زمني أولي. وميزانية. وتقديرات أخرى مهمة للعميل. كيف يجب أن يتعامل مدير المشروع مع هذا الموقف؟', 'A team is working on a project to deploy a new technology. The product has never been implemented before, so there is no historical data or record of previous projects to use. The team is asked to provide an initial schedule, budget, and other important estimates to the customer. How should the project manager handle this situation?', 'عند غياب البيانات التاريخية تُعد تقديرات أولية بمشاركة الفريق والخبراء، مع توضيح الافتراضات ونطاق عدم اليقين والقيود للعميل. يمكن استخدام نماذج أولية وتجارب فنية لتحسينها تدريجيًا. لا ينبغي عرض أرقام تفصيلية باعتبارها مؤكدة بلا أساس، ولا تكفي الإرشادات العامة أو الدروس المستفادة لتوفير التقديرات المطلوبة في الوقت الحالي.', 'When historical data is unavailable, initial estimates should be developed with the team and subject matter experts, while communicating the assumptions, uncertainty range, and constraints to the customer. Prototypes and technical experiments can improve the estimates over time. Detailed figures should not be presented as certain without a sound basis. General guidance and lessons learned alone do not provide the estimates currently requested.', 1),
  (1, 61, 'أثناء تفقد موقع المشروع. اكتشف مدير المشروع أن المقاول الباطن استبدل الكمرات الفولاذية المحددة في العقد بأخرى أقل تكلفة. ويدّعي المورد أن المواد الجديدة تتوافق مع المعايير الصناعية. بينما يحذر مسؤول ضمان الجودة من أنها لا تتوافق مع حدود التصميم المعتمدة. ويضغط راعي المشروع على مدير المشروع لقبول هذا التغيير لتجنب تكاليف إعادة العمل. في حين يؤكد مسؤول المشتريات أن ما حدث يمثل مخالفة للعقد. ماذا يجب أن يفعل مدير المشروع؟', 'During a project site inspection, the project manager discovers that the subcontractor has replaced the contract-specified steel beams with lower-cost alternatives. The supplier claims that the new materials meet industry standards, but the quality assurance manager warns that they do not comply with the approved design limits. The project sponsor pressures the project manager to accept the change to avoid rework costs, while the procurement manager confirms that this is a contract violation. What should the project manager do?', 'المواد يجب أن تطابق العقد والتصميم المعتمد، ولا يكفي توافقها مع معيار صناعي عام. تُوثق عدم المطابقة وتُطبق بنود العقد لإلزام المورد بتصحيحها وتحمل التكلفة وفق التزاماته. لا تبرر ضغوط الراعي قبول تغيير غير معتمد أو تغيير حدود التصميم لتغطية المخالفة. واستبدال المورد أو حجب المستحقات يخضع لإجراءات وصلاحيات العقد، ولا يُتخذ تلقائيًا.', 'The materials must comply with the contract and approved design; meeting a general industry standard is not sufficient. The project manager should document the nonconformance and enforce the contract terms so the supplier corrects it and bears the cost as required by its obligations. The sponsor’s pressure does not justify accepting an unapproved change or adjusting design limits to conceal the violation. Replacing the supplier or withholding payment must follow the contract’s procedures and authority, rather than being done automatically.', 1),
  (1, 62, 'يرغب راعي المشروع في التعاقد مع مقاول سبق أن تعاملت معه الشركة في مشاريع سابقة. وطلب من مدير المشروع تقديم تقييم لهذا المقاول. وتتطلب حوكمة المشتريات إجراء تقييم موضوعي وقابل للمراجعة للموردين لضمان العدالة والامتثال. ويحتاج مدير المشروع إلى تقديم تقييم بعيدًا عن تأثير راعي المشروع أو التحيز الشخصي أو الآراء الذاتية. ماذا يجب أن يفعل مدير المشروع؟', 'The project sponsor wants to contract with a vendor the company has used on previous projects and asks the project manager to assess the vendor. Procurement governance requires an objective, auditable evaluation of suppliers to ensure fairness and compliance. The project manager must provide an assessment without influence from the sponsor, personal bias, or subjective opinions. What should the project manager do?', 'التقييم الرسمي وفق معايير مسبقة ومتوافقة مع سياسة المشتريات يوفر أساسًا موضوعيًا وموثقًا يمكن تدقيقه. يمكن استخدام مؤشرات الأداء السابقة والخبرة الفنية ضمن الأدلة، مع تطبيق المعايير بالتساوي على المرشحين. نجاح علاقة سابقة أو رغبة الراعي لا يكفيان لإثبات أن المقاول هو الأنسب، والآراء غير الرسمية لا تحقق وحدها متطلبات الحوكمة.', 'A formal evaluation based on predefined criteria aligned with procurement policy provides an objective, documented, auditable basis. Historical performance indicators and technical experience may be used as evidence when the same criteria are applied to all candidates. A successful past relationship or sponsor preference alone does not prove that the vendor is the best fit, and informal opinions do not by themselves satisfy governance requirements.', 1),
  (1, 63, 'بعد تحليل مؤشرات الأداء أثناء تنفيذ المشروع، اكتشف مدير المشروع أن بعض المؤشرات تعطي صورة مضللة عن التقدم. رغم إنجاز عدد كبير من المخرجات، أوضح التحليل أن معظمها صغير أو جزئي أو منخفض الأهمية، بينما لا تزال أغلب المهام الأكثر تعقيدًا دون إنجاز. من الضروري استخدام مؤشرات أكثر فاعلية خلال ما تبقى من المشروع. ماذا يجب أن يفعل مدير المشروع؟', 'After analyzing performance indicators during project execution, the project manager discovers that some indicators give a misleading picture of progress. Although many deliverables have been completed, most are small, partial, or low in importance, while most of the more complex tasks remain unfinished. More effective indicators are needed for the remainder of the project. What should the project manager do?', 'يجب أن تقيس المؤشرات التقدم نحو أهداف المشروع وقيمة النتائج، بدلًا من الاكتفاء بعدّ المخرجات الصغيرة أو الجزئية. تُختار مقاييس تراعي أهمية العمل وجودته واكتماله، وتُراجع مع المعنيين. إضافة مؤشرات أو زيادة تواتر التقارير دون تغيير ما تقيسه لن تصلح التضليل. والعائد على الاستثمار قد يكون مفيدًا، لكنه لا يغطي كل أهداف المشروع بمفرده.', 'Indicators should measure progress toward project objectives and the value of outcomes, rather than simply count small or partial deliverables. The project manager should select measures that reflect the importance, quality, and completion of the work and review them with stakeholders. Adding indicators or increasing reporting frequency without changing what is measured will not correct the misleading picture. ROI may be useful, but it does not by itself cover every project objective.', 1),
  (1, 64, 'طلب قائد فريق تقنية المعلومات استخدام احتياطيات المشروع لتغطية بعض التحديثات. مؤكدًا أهمية هذه التحديثات. وأشار راعي المشروع إلى أن الموافقة على الطلب ستعزز العلاقة مع الإدارة العليا. في المقابل. أوضح المدير المالي أن الاحتياطيات جزء من خط أساس المشروع ولا يجوز استخدامها في أغراض أخرى. بينما حذر مدير المخاطر من أن الموافقة على الطلب ستجعل المشروع معرضًا للمخاطر المعروفة. ماذا يجب أن يفعل مدير المشروع؟', 'The IT team lead asks to use project reserves to pay for certain upgrades, emphasizing their importance. The project sponsor says approving the request would strengthen the relationship with senior management. The finance manager states that the reserves are part of the project baseline and cannot be used for other purposes, while the risk manager warns that approval would expose the project to known risks. What should the project manager do?', 'المقصود هنا احتياطي الطوارئ داخل خط الأساس والمخصص لمخاطر معروفة، فلا يُحوّل إلى تحديثات خارج غرضه لإرضاء الإدارة. يوضح المدير أثر الطلب في قدرة المشروع على الاستجابة ويستخدم إجراء التغيير والتمويل المناسب إذا كانت التحديثات لازمة. أما الاحتياطي الإداري للمخاطر غير المتوقعة فهو خارج خط الأساس وتخضع إدارته لصلاحيات مختلفة؛ ليست كل الاحتياطيات مقيدة بالمخاطر المحددة مسبقًا.', 'The reserve described is the contingency reserve within the cost baseline, allocated to identified risks; it should not be diverted to unrelated upgrades to satisfy management. The project manager should explain how the request would affect response capacity and use the appropriate change and funding process if the upgrades are required. Management reserve for unforeseen work is outside the baseline and has different authorization rules, so not all reserves are restricted to previously identified risks.', 1),
  (1, 65, 'يقوم مكتب إدارة المشاريع بمراجعة الوضع المالي لمشروع يقترب من الانتهاء. أكد القسم المالي سداد جميع مستحقات المقاولين وإغلاق العقود رسميًا. يرغب الراعي في التأكد من إمكانية إغلاق المشروع وإعادة توزيع الموارد على مشاريع أخرى. ماذا يجب أن يفعل مدير المشروع؟', 'A project management office (PMO) is reviewing the financial status of a project that is nearing completion. The finance department confirms that all contractor payments have been made and the contracts have been formally closed. The sponsor wants to know whether the project can be closed and resources reassigned to other projects. What should the project manager do?', 'سداد المقاولين وإغلاق العقود لا يعني اكتمال إغلاق المشروع كله. يتحقق المدير من اكتمال المخرجات وقبولها، ومن التقارير والسجلات المالية النهائية وبقية متطلبات الإغلاق، قبل تأكيد الجاهزية وإعادة توزيع الموارد. الجودة ورضا المعنيين عنصران مهمان ضمن هذا التحقق، لكن كل واحد منهما وحده لا يثبت اكتمال جميع الالتزامات.', 'Paying contractors and closing contracts does not mean the entire project closeout is complete. The project manager should verify that deliverables have been completed and accepted, final financial reports and records are in place, and other closeout requirements are met before confirming readiness and releasing resources. Quality and stakeholder satisfaction are important parts of this verification, but neither alone proves that all obligations are complete.', 1),
  (1, 66, 'يقود مدير مشروع مبادرة معقدة تتضمن مكونات للأجهزة (Hardware) والبرمجيات (Software). وافق العميل على خطة تفصيلية تعتمد على النهج التنبؤي (Predictive)، وتتضمن مخطط جانت (Gantt Chart) ثابتًا ونقاط مشاركة محددة للعميل. في الوقت نفسه، يقترح فريق البرمجيات استخدام ممارسات المنهج الرشيق (Agile) لتحسين سرعة التسليم وزيادة المرونة. ماذا يجب أن يفعل مدير المشروع؟', 'A project manager is leading a complex initiative with both hardware and software components. The customer has approved a detailed predictive plan with a fixed Gantt chart and specific customer engagement points. At the same time, the software team proposes using agile practices to improve delivery speed and flexibility. What should the project manager do?', 'يُختار أسلوب التنفيذ بحسب طبيعة المكونات ودرجة اليقين والتبعيات والحوكمة واحتياجات العميل. يمكن أن يناسب النهج الهجين مشروعًا يجمع أجهزة بمتطلبات مستقرة وبرمجيات تحتاج إلى تعلم وتكيف. لذلك يقيّم المدير البدائل ويحقق التوازن قبل أي تغيير معتمد. لا يفرض التحول الكامل إلى أجايل أو التمسك بالخطة الأصلية دون دراسة القيمة والمخاطر.', 'The delivery approach should be selected based on the nature of the components, uncertainty, dependencies, governance, and customer needs. A hybrid approach may suit a project that combines hardware with stable requirements and software that requires learning and adaptation. The project manager should assess alternatives and balance value before proposing an approved change. Neither a full switch to agile nor adherence to the original plan without analysis is appropriate.', 1),
  (1, 67, 'أثناء اجتماع لمراجعة المشروع، اكتشف مدير المشروع أن أحد الموردين لا يمتلك الشهادة المحدثة المطلوبة. يحذر مسؤول المشتريات من أن المورد يخالف شروط العقد. لتجنب التأخير، يطلب الراعي السماح للمورد بالاستمرار في العمل، بينما يؤكد العميل أن التعامل مع موردين معتمدين شرط أساسي في المشروع. ماذا يجب أن يفعل مدير المشروع لضمان الامتثال؟', 'During a project review meeting, the project manager discovers that a supplier does not have the required current certification. The procurement manager warns that the supplier is violating contract terms. To avoid a delay, the sponsor asks to let the supplier continue working, while the customer confirms that using certified suppliers is a project requirement. What should the project manager do to ensure compliance?', 'إذا كانت الشهادة شرطًا تعاقديًا وشرط قبول لدى العميل، فلا تستمر أعمال المورد المتأثرة دون التحقق من استيفائها. يُنسق إيقاف العمل المعني وتطبيق بنود العقد وخطة المعالجة، مع تقييم أثر ذلك في الجدول. تقديم طلب شهادة لا يعادل الحصول عليها، والحفاظ على الموعد لا يبرر تجاوز شرط امتثال ملزم.', 'If certification is a contractual requirement and a customer acceptance condition, the affected supplier work should not continue until compliance is verified. The project manager should coordinate a stop to the affected work, enforce contract terms, and follow the remediation plan while assessing schedule impacts. An application for certification is not the same as holding it, and preserving the schedule does not justify bypassing a mandatory compliance requirement.', 1),
  (1, 68, 'انتهى فريق التطوير من آخر مخرج في مشروع لتكامل الأنظمة. ويطالب المديرون الوظيفيون مدير المشروع بالإفراج عن أعضاء الفريق فورًا حتى يتمكنوا من الانضمام إلى مشروع جديد تمت الموافقة عليه ويحتاج إلى بدء سريع. وفي المقابل. يوضح مكتب إدارة المشاريع (PMO) أن هناك عدة أنشطة إلزامية خاصة بالحوكمة وإغلاق المشروع لم تكتمل بعد. ويؤكد ضرورة الالتزام الكامل بمتطلبات الحوكمة والتدقيق. كما يشدد راعي المشروع على أهمية البدء بالمشروع الجديد في أسرع وقت. ماذا يجب أن يفعل مدير المشروع؟', 'The development team has completed the final deliverable for a systems integration project. Functional managers ask the project manager to release the team immediately so its members can join a newly approved project that must start quickly. The project management office (PMO) states that several mandatory governance and project closeout activities are still incomplete and emphasizes compliance with governance and audit requirements. The project sponsor also stresses the need to start the new project as soon as possible. What should the project manager do?', 'يجب استكمال أنشطة الإغلاق والحوكمة الإلزامية والتحقق من القبول والتوثيق والأرشفة والموافقات، ثم الإفراج عن الموارد وفق خطة الإغلاق. انتهاء التطوير وحده لا يكفي لإغلاق المشروع. ويمكن التنسيق لنقل بعض الموارد عند انتفاء الحاجة إليها، بشرط إبقاء القدرة اللازمة لإكمال الإغلاق. تمديد التاريخ ليس أول حل إذا أمكن استكمال المتطلبات ضمن الخطة الحالية.', 'Mandatory closeout and governance activities must be completed, including verification of acceptance, documentation, archiving, and approvals, before resources are released in accordance with the closeout plan. Completion of development alone does not close the project. Some resources may be transferred when no longer needed, provided sufficient capacity remains to complete closeout. Extending the date is not the first solution if the requirements can be completed within the current plan.', 1),
  (1, 69, 'يعرض مدير المشروع نموذجًا أوليًا (Prototype) على العميل في منتصف مشروع تطوير نظام. ويلاحظ العميل أن هناك عدة خصائص رئيسية مفقودة. فيقوم بتصعيد الأمر إلى المعنيين الرئيسيين. ويؤكد راعي المشروع أن التنفيذ يسير وفق الخطة وأن المتطلبات قد تم توثيقها بشكل صحيح. بينما يؤكد فريق المشروع أنه نفذ العمل وفق خط أساس النطاق (Scope Baseline) وهيكل تجزئة العمل (WBS) المعتمدين. ويطلب المعنيون من مدير المشروع التحقق مما إذا كانت ملاحظات العميل صحيحة. وتقديم التوصية المناسبة مع الحفاظ على الجدول الزمني والميزانية والعلاقة مع المعنيين. ما أول إجراء يجب أن يقوم به مدير المشروع؟', 'A project manager presents a prototype to the customer midway through a system development project. The customer notices that several key features are missing and escalates the concern to key stakeholders. The sponsor confirms that execution is on plan and that the requirements were properly documented. The project team says it followed the approved scope baseline and work breakdown structure (WBS). Stakeholders ask the project manager to verify whether the customer’s feedback is valid and recommend an appropriate action while preserving the schedule, budget, and stakeholder relationship. What should the project manager do first?', 'يبدأ المدير بالتحقق من النطاق المعتمد والمتطلبات المتتبعة إليه لمعرفة ما إذا كانت الخصائص جزءًا من الالتزام أم طلبات إضافية. إذا كانت معتمدة، يُبحث سبب عدم تنفيذها ويُعالج الانحراف. وإذا كانت خارج النطاق، تُحلل عبر ضبط التغيير. طلب وقت أو مال أو تعديل التنفيذ قبل هذا التحقق قد يعالج مشكلة لم يتم تشخيصها بصورة صحيحة.', 'The project manager should first verify the approved scope and traceable requirements to determine whether the features are part of the commitment or additional requests. If they were approved, the manager should investigate why they were not implemented and address the variance. If they are outside scope, they should be analyzed through change control. Requesting time or money or changing execution before this verification may address a problem that has not been correctly diagnosed.', 1),
  (1, 70, 'يضغط راعي المشروع على مدير المشروع لتعديل مؤشرات العيوب قبل اجتماع المراجعة التنفيذي القادم. ويحذر مسؤول ضمان الجودة من أن هذا التصرف سيقوض الشفافية. بينما يشير المدير المالي إلى أن التلاعب بالبيانات قد يؤدي إلى إجراء تدقيق رسمي. ماذا يجب أن يفعل مدير المشروع؟', 'The project sponsor pressures the project manager to alter defect metrics before the next executive review meeting. The quality assurance manager warns that doing so would undermine transparency, while the finance manager notes that manipulating the data could trigger a formal audit. What should the project manager do?', 'يقدم المدير بيانات دقيقة وصريحة، مع تفسير الانحرافات وخطة التصحيح. التلاعب بمؤشرات العيوب يضر الثقة ويخفي معلومات يحتاجها المعنيون لاتخاذ القرار، ولا تجيزه رغبة الراعي. يجوز تصحيح خطأ مثبت في البيانات مع توثيق التصحيح، لكن تحسين المظهر دون أساس مختلف عن ذلك. وتأجيل التقرير عمدًا لإخفاء الوضع لا يحقق الشفافية المطلوبة.', 'The project manager should present accurate, candid data, explain variances, and describe the corrective action plan. Manipulating defect metrics damages trust and conceals information stakeholders need for decisions; the sponsor’s preference does not authorize it. A verified data error may be corrected with the correction documented, but that differs from changing figures to improve appearances. Deliberately delaying a report to hide the situation does not meet transparency requirements.', 1),
  (1, 71, 'أصبح راعي المشروع يشعر بقلق متزايد بشأن القيمة التي يحققها المشروع. ويريد التأكد من أن المشروع يسير وفق الجدول الزمني ويحقق المنافع المتوقعة. ماذا يجب أن يفعل مدير المشروع لتقديم دليل موضوعي على أداء المشروع؟', 'The project sponsor is increasingly concerned about the value the project is delivering and wants to confirm that it is on schedule and will realize the expected benefits. What should the project manager do to provide objective evidence of project performance?', 'مقارنة الأداء الفعلي بالتوقعات وخطوط الأساس ومعايير المنافع توضح حجم الانحراف واتجاهه وتوفر دليلًا قابلًا للتحقق. يُبيّن المدير ما تحقق وما يتوقع تحقيقه والإجراءات عند الحاجة. حضور الاجتماعات أو زيادة عدد التقارير لا يضمنان دليلًا موضوعيًا، وعرض نتائج نقطة مراجعة واحدة دون مقارنتها بالأهداف قد يعطي صورة ناقصة.', 'Comparing actual performance with forecasts, baselines, and benefit measures shows the size and direction of variances and provides verifiable evidence. The project manager should explain what has been achieved, what is forecast, and any actions required. Attendance at standups or more reports does not necessarily provide objective evidence, and presenting one milestone’s results without comparing them with objectives may give an incomplete picture.', 1),
  (1, 72, 'تم تقدير المشروع ليشمل 250 نقطة قصة (Story Points). خطط الفريق لإنجاز 40 نقطة قصة في كل تكرار، لكنه أنجز خلال أول أربعة تكرارات: 40 نقطة في الأول، و10 نقاط في الثاني، و20 نقطة في الثالث، و15 نقطة في الرابع. ماذا يجب أن يفعل مدير المشروع؟', 'A project is estimated at 250 story points. The team plans to complete 40 story points per iteration but completes 40 points in the first iteration, 10 in the second, 20 in the third, and 15 in the fourth. What should the project manager do?', 'الإنجاز الفعلي في أربعة تكرارات هو 85 نقطة، بمتوسط 21.25 نقطة للتكرار، وهو أقل من التخطيط البالغ 40 نقطة. يتعاون الفريق لتحديد أسباب التباين وتحديث توقعاته والالتزام القادم وفق قدرته الفعلية. هذا المتوسط مؤشر أولي وليس ضمانًا. تُراجع آثار التوقع الجديد مع مالك المنتج والعميل، ولا تُحذف خصائص أو يُغيَّر موعد التسليم من طرف واحد.', 'The team completed 85 points over four iterations, an average of 21.25 points per iteration, below the planned 40. The team should identify the causes of the variance and update its forecast and future commitments based on its actual capacity. This average is an initial indicator, not a guarantee. The revised forecast should be reviewed with the product owner and customer; features or delivery dates should not be changed unilaterally.', 1),
  (1, 73, 'يعمل مدير مشروع في شركة ناشئة سريعة النمو تسمح بساعات عمل مرنة والعمل عن بُعد. خلال اجتماع الدروس المستفادة الأخير، ذكر أحد أعضاء الفريق أن سرعة الإنجاز (Velocity) كانت أعلى عندما كان الجميع يعملون معًا في غرفة المشروع. يرغب المدير في التعامل مع هذه الملاحظة دون التأثير على ثقافة العمل المرنة داخل الشركة. ماذا يجب أن يفعل؟', 'A project manager works at a fast-growing start-up that allows flexible hours and remote work. During the latest lessons learned meeting, a team member says velocity was higher when everyone worked together in the project room. The project manager wants to address the observation without undermining the company’s flexible work culture. What should the project manager do?', 'الملاحظة بشأن العمل في مكان واحد فرضية تحتاج إلى فهم جماعي وبيانات. يجمع المدير آراء الفريق ويفحص الظروف التي حسنت السرعة، ثم يمكن تجربة ترتيبات تعاون مناسبة ومقارنة النتائج مع احترام سياسة المرونة. لا تُغيّر سياسة المؤسسة أو يُفرض الحضور بسبب تجربة واحدة، ولا تعالج إعادة ترتيب السجل سبب الإنتاجية قبل التحقق منه.', 'The observation about working in one location is a hypothesis that should be explored with the team and supported by data. The project manager should gather team members’ views and examine the conditions that improved velocity, then consider suitable collaboration experiments and compare results while respecting the flexible work policy. One experience does not justify changing organization-wide policy or requiring office attendance. Reprioritizing the backlog will not address productivity before its cause is understood.', 1),
  (1, 74, 'تم تعيين مدير مشروع لإدارة مشروع مشابه في النطاق والتعقيد لمشروع سابق. يوضح الراعي أن المشروع السابق شهد تقديرًا أقل من الواقع لتكاليف عدد من الأنشطة، كما أثرت عدة أحداث غير متوقعة بصورة كبيرة في الميزانية. تطلب الإدارة العليا أن يظهر المشروع الجديد مستوى أعلى من الانضباط في التخطيط من خلال قياس التعرض للمخاطر والاستفادة من الخبرات السابقة وتخصيص احتياطيات طوارئ مناسبة. ما أول إجراء يجب أن يقوم به مدير المشروع؟', 'A project manager is assigned to a project similar in scope and complexity to a previous project. The sponsor explains that the previous project underestimated the cost of several activities and that unexpected events significantly affected the budget. Senior management wants stronger planning discipline on the new project by measuring risk exposure, using prior experience, and allocating appropriate contingency reserves. What should the project manager do first?', 'تقدم الدروس السابقة نقطة بداية لفهم أسباب نقص التقدير والأحداث التي أثرت في التكلفة والاستجابات التي نجحت. يُحلل المدير مدى انطباقها على المشروع الجديد، ثم يحدد المخاطر ويقدر التعرض لها ويخطط الاحتياطيات. توثيق أخطاء التقدير مهم ضمن التحليل، لكن توزيع الموارد أو تقديم الأنشطة عالية المخاطر ليس بديلًا عن فهم التعرض أولًا.', 'Lessons from the previous project provide a starting point for understanding the causes of underestimation, the events that affected cost, and the responses that worked. The project manager should assess how applicable they are to the new project, then identify risks, estimate exposure, and plan reserves. Documenting estimation errors is important as part of the analysis, but assigning resources or scheduling high-risk activities early does not replace understanding the exposure first.', 1),
  (1, 75, 'يقوم مدير مشروع بتشكيل فريق مشروع جديد. ويكتشف وجود تعارضات مع مشاريع أخرى قائمة. وتعود هذه التعارضات إلى محدودية توفر أعضاء الفريق، ومحدودية توفر المراجعين الخارجيين، والتنافس على الموارد المشتركة. ويقع على عاتق مدير المشروع مسؤولية تحديد وتأمين الموارد اللازمة لنجاح المشروع. ماذا يجب أن يفعل مدير المشروع؟', 'A project manager is assembling a new project team and discovers conflicts with other ongoing projects. The conflicts are caused by limited availability of team members and external reviewers and competition for shared resources. The project manager is responsible for identifying and securing the resources needed for project success. What should the project manager do?', 'التنافس بين المشاريع على موارد محدودة يحتاج إلى تنسيق على مستوى يمتلك سلطة تحديد الأولويات وتخصيص الموارد. يناقش المدير التعارضات مع الإدارة العليا أو الجهة المخولة للحصول على خطة واقعية لتأمين الفريق والمراجعين. يقدم بيانات الاحتياج والأثر وبدائل الحل. تأجيل المهام أو فرض العمل الإضافي دون اتفاق قد ينقل المشكلة إلى مشاريع أخرى.', 'Competition among projects for limited resources requires coordination at a level with authority to set priorities and allocate resources. The project manager should discuss the conflicts with senior management or the authorized body and obtain a realistic plan to secure the team and reviewers. The manager should provide resource needs, impacts, and alternatives. Deferring tasks or imposing overtime without agreement may simply transfer the problem to other projects.', 1),
  (1, 76, 'تستعد شركة عالمية لإطلاق منتج جديد. ومع اقتراب المشروع من نهايته. أبلغ مدير المشروع بوجود خلاف بين المستخدمين النهائيين حول وظيفة إحدى خصائص المنتج. ويحتاج مدير المشروع إلى الحصول على موافقة المعنيين قبل إغلاق المشروع. ما الإجراءان اللذان يجب على مدير المشروع القيام بهما؟ (اختر إجابتين)', 'A global company is preparing to launch a new product. Near the end of the project, the project manager is informed of a disagreement among end users about the functionality of one product feature. The project manager needs stakeholder approval before closing the project. What two actions should the project manager take? (Choose two.)', 'تُراجع مع المعنيين معايير القبول المتفق عليها، ويُتحقق كذلك من تعريف الإنجاز لتحديد ما إذا كانت الخاصية تلبي المتطلبات والجودة المطلوبة. إذا كشفت المراجعة عيبًا يُعالج، وإذا ظهر احتياج جديد يُدار كتغيير. لا يُغلق المشروع مع خلاف غير محسوم على القبول، ولا تؤجل المشكلة تلقائيًا إلى إصدار لاحق دون موافقة مناسبة.', 'The project manager should review the agreed acceptance criteria with stakeholders and also verify the Definition of Done to determine whether the feature meets the required requirements and quality. If the review identifies a defect, it should be addressed; if it identifies a new need, it should be managed as a change. The project should not be closed with an unresolved acceptance dispute, and the issue should not automatically be deferred to a later release without appropriate approval.', 2),
  (1, 77, 'أثناء اجتماع لمراجعة المشروع مع المعنيين. عرض مدير المشروع تقرير أداء المشروع. طلب أحد المعنيين الاطلاع على جميع البيانات الخام لضمان الشفافية الكاملة. بينما اشتكى معني آخر من أن التقارير الحالية تحتوي على تفاصيل أكثر من اللازم. ماذا يجب أن يفعل مدير المشروع؟', 'During a project review meeting, the project manager presents a project performance report. One stakeholder asks to see all raw data for complete transparency, while another complains that the current reports contain too much detail. What should the project manager do?', 'بيانات أداء العمل هي الملاحظات والقياسات الخام، ثم تُحلل في سياقها لتصبح معلومات أداء، وتُعرض في تقارير تناسب احتياجات الجمهور. يوضح المدير هذه العلاقة ويحدد مستوى التفصيل والتواتر المناسب لكل فئة. لا تعني الشفافية إرسال كل البيانات إلى الجميع، ولا تعني الملخصات إخفاء الأدلة؛ تُتاح التفاصيل اللازمة وفق خطة التواصل والصلاحيات.', 'Work performance data consists of raw observations and measurements. It is analyzed in context to become work performance information and presented in reports suited to the audience. The project manager should explain this relationship and set an appropriate level of detail and frequency for each group. Transparency does not require sending all data to everyone, and summaries should not conceal evidence; relevant details should be available according to the communications plan and access permissions.', 1),
  (1, 78, 'يحتاج مدير المشروع إلى اقتراح منهجية مناسبة لمشروع تطوير برمجيات يتميز بدرجة عالية من عدم اليقين ومتطلبات تتغير وتتطور باستمرار. رغم أن الفريق يفضل استخدام المنهجية التكيفية (Adaptive)، يرى أحد المعنيين الرئيسيين أنه ينبغي دراسة منهجيات أخرى أيضًا. ما الذي يجب أن يؤكد عليه المدير لإقناع هذا المعني بأن المنهجية الرشيقة هي الأنسب؟', 'A project manager needs to recommend an appropriate approach for a software development project characterized by high uncertainty and continuously evolving requirements. The team prefers an adaptive approach, but a key stakeholder believes other approaches should also be considered. What should the project manager emphasize to convince the stakeholder that an agile approach is the best fit?', 'ارتفاع عدم اليقين وتطور المتطلبات يجعلان التعلم المتكرر والتفاعل مع المعنيين أساسًا لاختيار النهج التكيفي. تسمح الزيادات القصيرة والملاحظات بإعادة ترتيب العمل والتحقق من القيمة. المتطلبات الثابتة وسهولة التنبؤ تميل إلى دعم نهج تنبؤي، بينما طبيعة المشروع هنا تحتاج إلى المرونة. ويجب تقييم القيود والحوكمة أيضًا عند اختيار دورة الحياة.', 'High uncertainty and evolving requirements make iterative learning and stakeholder interaction central to selecting an adaptive approach. Short increments and feedback allow the team to reprioritize work and validate value. Stable requirements and predictability tend to support a predictive approach, while this project needs flexibility. Constraints and governance should also be assessed when selecting the life cycle.', 1),
  (1, 79, 'يقوم مدير مشروع بإعداد تقرير الحالة الأسبوعي. تشير البيانات إلى أنه أنفق حتى الآن 20,000 دولار. حتى تاريخ اليوم، أنجز أعمالًا بقيمة 12,000 دولار، بينما كانت الخطة الأصلية تقضي بإنجاز أعمال بقيمة 10,000 دولار فقط بحلول هذا التاريخ. كيف ينبغي أن يبلغ عن انحراف الجدول الزمني (Schedule Variance)؟', 'A project manager is preparing the weekly status report. The data show that $20,000 has been spent to date. By today, work worth $12,000 has been completed, while the original plan called for only $10,000 worth of work to be completed by this date. How should the project manager report the schedule variance (SV)?', 'انحراف الجدول في القيمة المكتسبة يساوي القيمة المكتسبة ناقص القيمة المخططة: 12,000 ناقص 10,000، فيكون موجب 2,000 دولار. تعني الإشارة الموجبة إنجاز قيمة عمل أعلى من المخطط عند تاريخ القياس. أما 20,000 فهي التكلفة الفعلية وتستخدم لحساب انحراف التكلفة، الذي يساوي سالب 8,000. انحراف الجدول هنا يقاس بوحدات مالية، ولا يحدد وحده عدد أيام التقدم.', 'Earned value schedule variance is earned value minus planned value: $12,000 − $10,000 = positive $2,000. A positive value means more work value has been completed than planned as of the status date. The $20,000 is actual cost and is used to calculate cost variance, which is −$8,000. Schedule variance is expressed in monetary units here and does not, by itself, indicate the number of days ahead.', 1),
  (1, 80, 'يُطلب من مدير المشروع المساهمة في إعداد مستند يصف ما سيتم تحقيقه بالمشروع بمجرد الانتهاء منه بنجاح، وكيف سيتم قياس ذلك. ما اسم هذا المستند؟', 'A project manager is asked to contribute to a document that describes what will be achieved when the project is successfully completed and how achievement will be measured. What is this document called?', 'خطة إدارة المنافع تحدد المنافع المتوقعة ومقاييس تحققها وتوقيت قياسها والمسؤول عن متابعتها، وقد تمتد المتابعة إلى ما بعد انتهاء المشروع. وهي الأنسب لوصف ما سيحققه المشروع وكيف تُقاس نتائجه. بيان النطاق يصف المخرجات، وخطة إدارة المشروع توضح التنفيذ والإدارة، وخطة التغيير تنظم تعديل الالتزامات، ولا يحل أي منها محل خطة المنافع.', 'The benefits management plan defines the expected benefits, how and when they will be measured, and who is responsible for tracking them. It is the best fit for describing what the project is expected to achieve and how results will be measured. The scope statement describes deliverables, the project management plan describes how the work is managed, and the change management plan governs changes to commitments; none replaces the benefits management plan.', 1),
  (1, 81, 'على مدار الاثني عشر شهرًا الماضية، قام مدير المشروع بمتابعة تقدم الفريق باستخدام نقاط القصص لقياس حجم العمل المنجز، وأعد مخطط العمل المتبقي لعرض تقدم كل تكرار على المعنيين خلال الفترة من يناير إلى ديسمبر. ماذا يجب أن يبلغ المعنيين بشأن تقدم المشروع استنادًا إلى المخطط؟
INSERT INTO new_questions (exam_no, question_index, text_ar, text_en, explanation_ar, explanation_en, answer_count) VALUES
  (2, 44, 'يحتاج مدير مشروع في مؤسسة ذات هيكل مصفوفي متوازن إلى مطوّر أول بدوام كامل لمرحلة تسليم حرجة مدتها ستة أسابيع. وقد وافق المدير الوظيفي على توفير المطوّر بدوام جزئي فقط، متذرعًا بالتزامات القسم. واستمرت المفاوضات المباشرة أسبوعين دون التوصل إلى حل، ولم يتبقَّ على موعد بدء المرحلة سوى أسبوع واحد.
INSERT INTO new_choices (exam_no, question_index, position, text_ar, text_en, is_correct) VALUES
  (0, 0, 0, 'توجيه الفريق إلى تنفيذ المتطلبات فورًا لأنها إلزامية.', 'Direct the team to implement the requirements immediately because they are mandatory.', false),
  (0, 0, 1, 'رفض المتطلبات لأنها لم تكن ضمن خط الأساس الأصلي.', 'Reject the requirements because they were not part of the original baseline.', false),
  (0, 0, 2, 'تقييم أثر المتطلبات على المشروع وتحديد الإجراء المناسب وفق عملية التغيير.', 'Assess the impact of the requirements on the project and determine the appropriate action through the change control process.', true),
  (0, 0, 3, 'مطالبة الراعي بزيادة الميزانية قبل تحليل المتطلبات.', 'Ask the sponsor to increase the budget before analyzing the requirements.', false),
  (0, 1, 0, 'تصعيد الخلاف مباشرة إلى الراعي.', 'Escalate the disagreement directly to the sponsor.', false),
  (0, 1, 1, 'استبدال أعضاء الفريق الذين يرفضون التعاون.', 'Replace the team members who refuse to collaborate.', false),
  (0, 1, 2, 'تسهيل نقاش تعاوني بين الطرفين لفهم مصدر الخلاف والوصول إلى حل مشترك.', 'Facilitate a collaborative discussion between the two parties to understand the source of the disagreement and reach a shared solution.', true),
  (0, 1, 3, 'مطالبة فريق العمليات بعدم تغيير المتطلبات حتى نهاية المشروع.', 'Ask the operations team not to change requirements until the end of the project.', false),
  (0, 2, 0, 'الالتزام بالخطة الأصلية لمنع Scope Creep.', 'Stick to the original plan to prevent scope creep.', false),
  (0, 2, 1, 'العمل مع أصحاب المصلحة والفريق لإعادة تقييم الأولويات استنادًا إلى القيمة وملاحظات المستخدمين.', 'Work with stakeholders and the team to reassess priorities based on value and user feedback.', true),
  (0, 2, 2, 'مطالبة الراعي بتحديد الخصائص التي يجب حذفها.', 'Ask the sponsor to decide which features should be removed.', false),
  (0, 2, 3, 'تأجيل معالجة المشكلة حتى إغلاق المشروع.', 'Postpone addressing the problem until project closure.', false),
  (0, 3, 0, 'استخدام احتياطي الإدارة فورًا.', 'Use the management reserve immediately.', false),
  (0, 3, 1, 'استبدال المورد فورًا.', 'Replace the supplier immediately.', false),
  (0, 3, 2, 'تقييم التهديد وتأثيره ومراجعة استجابة المخاطر المناسبة.', 'Assess the threat and its impact, and review the appropriate risk response.', true),
  (0, 3, 3, 'تمديد الجدول الزمني للمشروع.', 'Extend the project schedule.', false),
  (0, 4, 0, 'عدد الخصائص التي تم إنجازها مقارنة بالخطة الأصلية فقط.', 'Only the number of features completed compared with the original plan.', false),
  (0, 4, 1, 'القيمة والنتائج المحققة مع توضيح أثر إعادة ترتيب الأولويات.', 'The value and outcomes achieved, while explaining the impact of reprioritization.', true),
  (0, 4, 2, 'إقناع الإدارة بأن الجدول الزمني لم يعد مهمًا في المشاريع الهجينة.', 'Convincing management that the schedule no longer matters in hybrid projects.', false),
  (0, 4, 3, 'مطالبة فريق التطوير بزيادة ساعات العمل لاستكمال جميع الخصائص.', 'Asking the development team to work more hours to complete all the features.', false),
  (0, 5, 0, 'تنفيذ الطلب لأن صاحب المصلحة يتمتع بقوة عالية.', 'Implement the request because the stakeholder has high power.', false),
  (0, 5, 1, 'رفض الطلب لأنه لم يكن ضمن الخطة الأصلية.', 'Reject the request because it was not part of the original plan.', false),
  (0, 5, 2, 'تقييم القيمة والأولوية والأثر مع الأطراف المناسبة قبل تحديد كيفية إدراجه في العمل المستقبلي.', 'Assess the value, priority, and impact with the appropriate parties before determining how to include it in future work.', true),
  (0, 5, 3, 'تقديم Change Request رسمي مباشرة إلى مجلس التحكم بالتغيير (CCB).', 'Submit a formal change request directly to the change control board (CCB).', false),
  (0, 6, 0, 'الانتظار حتى يقع التأخير فعليًا ثم تسجيله كمشكلة.', 'Wait until the delay actually occurs and then record it as an issue.', false),
  (0, 6, 1, 'تنفيذ استجابة المخاطر المتفق عليها ومراقبة فعاليتها.', 'Implement the agreed risk response and monitor its effectiveness.', true),
  (0, 6, 2, 'تصعيد الخطر مباشرة إلى الإدارة العليا دون اتخاذ أي إجراء.', 'Escalate the risk directly to senior management without taking any action.', false),
  (0, 6, 3, 'إعادة تحديد خط الأساس للجدول الزمني فورًا.', 'Rebaseline the schedule immediately.', false),
  (0, 7, 0, 'استخدام الأداة فورًا لأن الذكاء الاصطناعي سيقلل الوقت والتكلفة.', 'Use the tool immediately because AI will reduce time and cost.', false),
  (0, 7, 1, 'منع استخدام الذكاء الاصطناعي في المشروع بالكامل.', 'Prohibit the use of AI on the project entirely.', false),
  (0, 7, 2, 'تقييم المخاطر والضوابط والامتثال وجودة البيانات قبل اعتماد الأداة في عملية اتخاذ القرار.', 'Assess the risks, controls, compliance, and data quality before adopting the tool in the decision-making process.', true),
  (0, 7, 3, 'السماح للمورد باستخدام الأداة دون إبلاغ أصحاب المصلحة ما دامت النتائج ستراجع يدويًا.', 'Allow the supplier to use the tool without informing stakeholders, as long as the results will be reviewed manually.', false),
  (0, 8, 0, 'تجاهل البديل لأن الاستدامة ليست جزءًا من قيود المشروع التقليدية.', 'Ignore the alternative because sustainability is not one of the traditional project constraints.', false),
  (0, 8, 1, 'اختيار البديل الأقل استهلاكًا للطاقة فورًا دون تحليل أثره.', 'Select the lower-energy alternative immediately without analyzing its impact.', false),
  (0, 8, 2, 'تقييم البدائل من منظور القيمة الكلية والتكلفة والمخاطر والاستدامة، ثم إشراك أصحاب القرار المناسبين.', 'Evaluate the alternatives in terms of overall value, cost, risk, and sustainability, then involve the appropriate decision makers.', true),
  (0, 8, 3, 'تأجيل مناقشة الاستدامة إلى ما بعد إغلاق المشروع.', 'Postpone the sustainability discussion until after the project is closed.', false),
  (0, 9, 0, 'إلزام الفريق بتنفيذ جميع الخصائص المخططة قبل الإطلاق مهما كان أثر ذلك على الجدول.', 'Require the team to deliver all planned features before launch, regardless of the impact on the schedule.', false),
  (0, 9, 1, 'إلغاء الخصائص المتبقية مباشرة لأن المستخدمين راضون عن النسخة الحالية.', 'Cancel the remaining features immediately because users are satisfied with the current version.', false),
  (0, 9, 2, 'العمل مع أصحاب المصلحة المناسبين لإعادة تقييم الأولويات وخيارات التسليم بما يحمي القيمة والامتثال وموعد الإطلاق.', 'Work with the appropriate stakeholders to reassess priorities and delivery options in a way that protects value, compliance, and the launch date.', true),
  (0, 9, 3, 'طلب زيادة الميزانية لأن التأخر في الأنشطة الحرجة يعني أن المشروع قد فشل.', 'Request a budget increase because delays in critical activities mean the project has failed.', false),
  (0, 10, 0, 'الاجتماع مع عضو الفريق لمراجعة الموقف بمزيد من التفصيل', 'Meet privately with the team member to discuss the situation in more detail.', true),
  (0, 10, 1, 'الاجتماع مع الفريق لمناقشة البدائل الممكنة للتعامل مع هذا الموقف', 'Meet with the team to discuss possible alternatives for handling the situation.', false),
  (0, 10, 2, 'مطالبة إدارة الموارد البشرية بمعالجة موقف عضو الفريق', 'Ask Human Resources to address the team member’s situation.', false),
  (0, 10, 3, 'مطالبة راعي المشروع بتحديد كيفية تعامل الفريق مع هذا الموقف', 'Ask the project sponsor to determine how the team should handle the situation.', false),
  (0, 11, 0, 'تنظيم اجتماع مع مدير المبيعات الإقليمي وفريقه لتحديد احتياجاتهم وأولوياتهم. ثم طرح المقترح للمناقشة في اجتماع المشروع القادم', 'Meet with the regional sales manager and the team to identify their needs and priorities, then bring the proposal to the next project meeting for discussion.', true),
  (0, 11, 1, 'توجيه مدير المبيعات الإقليمي إلى استخدام أداة متابعة المشروع لإضافة طلبات الوظائف الجديدة', 'Tell the regional sales manager to use the project tracking tool to add the new feature requests.', false),
  (0, 11, 2, 'توضيح أن نطاق المشروع لا يمكن تغييره بهذه الطريقة. وأنه يجب تنفيذ المشروع كما هو', 'Explain that the project scope cannot be changed this way and that the project must be delivered as planned.', false),
  (0, 11, 3, 'إضافة المتطلبات الجديدة إلى النطاق. وتعديل الجدول الزمني وفقًا لطلب مدير المبيعات الإقليمي. ثم إرساله إلى راعي المشروع للموافقة', 'Add the new requirements to the scope, adjust the schedule as requested, and then send it to the project sponsor for approval.', false),
  (0, 12, 0, 'إجراء جلسة لتوليد الأفكار مع فريق المشروع لتحديد ما يمكن تسليمه بنجاح. ثم التفاوض للوصول إلى حل يلبي احتياجات راعي المشروع', 'Hold a brainstorming session with the project team to determine what can be delivered successfully, then negotiate a solution that meets the sponsor’s needs.', true),
  (0, 12, 1, 'تأكيد أن الفريق سيحقق النتائج المتوقعة. ثم إبلاغ فريق المشروع بهذا الالتزام لاحقًا', 'Confirm that the team will achieve the expected outcomes, then inform the team of this commitment later.', false),
  (0, 12, 2, 'إبلاغ راعي المشروع فورًا بأن توقعاته يستحيل تحقيقها. واقتراح إنهاء المشروع', 'Immediately tell the sponsor that the expectations are impossible and recommend ending the project.', false),
  (0, 12, 3, 'التواصل مع المعنيين للحصول على آرائهم الأولية بشأن كيفية التعامل مع توقعات راعي المشروع', 'Contact stakeholders to obtain their initial views on how to handle the sponsor’s expectations.', false),
  (0, 13, 0, 'إعداد خطة تفصيلية لإشراك المعنيين توضح كيفية إشراك الأطراف ذات الصلة.', 'Develop a detailed stakeholder engagement plan that explains how the relevant parties will be engaged.', true),
  (0, 13, 1, 'عقد اجتماع مع الإدارة العليا لمناقشة التعارضات المحتملة وطلب خطة للحل', 'Meet with senior management to discuss potential conflicts and request a resolution plan.', false),
  (0, 13, 2, 'إبلاغ المعنيين بسياسة العمل الإضافي وتحذير مديري المشروعات من توقع قيود مؤقتة في الموارد.', 'Inform stakeholders about the overtime policy and warn project managers to expect temporary resource constraints.', false),
  (0, 13, 3, 'إدراك المنافسة المحتملة على الموارد وتحديد المهام التي يمكن تأجيلها إلى مرحلة لاحقة.', 'Recognize the potential resource competition and identify tasks that could be deferred to a later phase.', false),
  (0, 14, 0, 'زيادة مستوى الكفاءة من خلال تقسيم العمل إلى وحدات أصغر.', 'Increase efficiency by dividing the work into smaller units.', false),
  (0, 14, 1, 'زيادة عدد الموارد المخصصة لتسريع العمل', 'Increase the number of assigned resources to accelerate the work.', false),
  (0, 14, 2, 'زيادة استخدام التكنولوجيا لأتمتة بعض المهام.', 'Increase the use of technology to automate some tasks.', false),
  (0, 14, 3, 'رفع مستوى الكفاءة والمهارة لدى الموارد المخصصة.', 'Improve the efficiency and skills of the assigned resources.', true),
  (0, 15, 0, 'تسهيل توضيح معايير القبول مع المعنيين. وتحديث وثائق نطاق المشروع رسميًا.', 'Facilitate clarification of acceptance criteria with stakeholders and formally update the project scope documentation.', true),
  (0, 15, 1, 'توصية راعي المشروع بالتفاوض مباشرةً مع العميل لمنع المزيد من حالات الرفض وتأخيرات الجدول الزمني.', 'Recommend that the sponsor negotiate directly with the customer to prevent further rejections and schedule delays.', false),
  (0, 15, 2, 'الموافقة فورًا على إعادة العمل لإرضاء العميل. ثم تعديل وثائق خط الأساس وفقًا لذلك.', 'Approve the rework immediately to satisfy the customer, then update the baseline documents.', false),
  (0, 15, 3, 'تصعيد الخلاف إلى الإدارة العليا للمشروع لأنها تحتاج إلى اتخاذ إجراء لتجنب الغرامات المالية.', 'Escalate the disagreement to senior project management because action is needed to avoid financial penalties.', false),
  (0, 16, 0, 'تقليل مخرجات المشروع لتحقيق استخدام أكثر ترشيدًا للموارد. ومراجعة خطة إدارة المشروع.', 'Reduce the project deliverables to optimize resource use and review the project management plan.', false),
  (0, 16, 1, 'مراجعة تاريخ القرارات المتعلقة بهذا المخرج لمعرفة متى بدأ الاستخدام المفرط للموارد.', 'Review the history of decisions about this deliverable to determine when excessive resource use began.', false),
  (0, 16, 2, 'تحديث خطة الرؤية لتقليل النطاق الطموح بشكل زائد المتعلق بترشيد استخدام الموارد.', 'Update the vision plan to reduce the overly ambitious scope related to resource optimization.', false),
  (0, 16, 3, 'تحليل الموقف وتحديد السبب الجذري للمشكلة من أجل اختيار أفضل حل.', 'Analyze the situation and identify the root cause of the problem to select the best solution.', true),
  (0, 17, 0, 'إشراك جميع أصحاب المصلحة المعنيين في تخطيط المشروع', 'Involve all relevant stakeholders in project planning.', true),
  (0, 17, 1, 'إعداد خطة لإدارة التغيير من أجل اعتماد التغييرات', 'Develop a change management plan to approve changes.', false),
  (0, 17, 2, 'إدارة توقعات جميع أصحاب المصلحة المعنيين.', 'Manage the expectations of all relevant stakeholders.', false),
  (0, 17, 3, 'الاستعانة برأي الخبراء عند تصميم نطاق المشروع', 'Use expert judgment when defining the project scope.', false),
  (0, 18, 0, 'تسهيل مناقشة بين أعضاء الفريق لمراجعة أصول عمليات المؤسسة (OPAs) والاتفاق على القواعد الأساسية للفريق.', 'Facilitate a team discussion to review organizational process assets (OPAs) and agree on team ground rules.', true),
  (0, 18, 1, 'عقد اجتماع انطلاق المشروع لمراجعة خطة إدارة المشروع.', 'Hold a project kickoff meeting to review the project management plan.', false),
  (0, 18, 2, 'استخدام إرشادات الشركة المحددة مسبقًا لوضع توقعات السلوك داخل الفريق.', 'Use the company’s predefined guidelines to set behavioral expectations for the team.', false),
  (0, 18, 3, 'طلب استبدال عضو الفريق المثير للمشكلات وتوفير بديل له قبل بدء المشروع.', 'Ask to replace the disruptive team member before the project starts.', false),
  (0, 19, 0, 'تنظيم جلسة مع أعضاء الفريق المناسبين لمراجعة تسجيلات فيديو للمراحل التي واجه فيها الفريق مشكلات موثقة', 'Organize a session with relevant team members to review video recordings of project phases where documented problems occurred.', false),
  (0, 19, 1, 'دمج النتائج في خطط المشروع لضمان إدراج الأفكار والخبرات المهمة في المشروعات والمراحل القادمة.', 'Integrate the findings into project plans so important insights and experience are incorporated into upcoming projects and phases.', true),
  (0, 19, 2, 'مراجعة السجلات المحفوظة في نظام معلومات إدارة المشروع للحصول على تفاصيل عن جهود إدارة المخاطر والاستجابة لها في الماضي.', 'Review records in the project management information system for details about past risk management and responses.', false),
  (0, 19, 3, 'إجراء مقابلات مع أصحاب المصلحة المعنيين لفهم مخاوفهم. واستخدام ملاحظاتهم في تحسين نطاق المشروعات الجديدة.', 'Interview relevant stakeholders to understand their concerns and use their feedback to improve the scope of new projects.', false),
  (0, 20, 0, 'التحقق من الوفاء بجميع الالتزامات التعاقدية والقانونية لمنع حدوث أي مشكلات قانونية مستقبلية.', 'Verify that all contractual and legal obligations have been met to prevent future legal issues.', false),
  (0, 20, 1, 'عقد جلسات لمشاركة المعرفة ونقل رؤى الفريق والدروس المستفادة إلى فريق الإنتاج', 'Hold knowledge-sharing sessions to transfer the team’s insights and lessons learned to the production team.', false),
  (0, 20, 2, 'تحديد المخاطر المعلقة التي ينبغي قبولها أو نقل مسؤوليتها إلى فريق الإنتاج.', 'Identify outstanding risks that should be accepted or transferred to the production team.', true),
  (0, 20, 3, 'مراجعة سجلات المشروع للتأكد من أنها تعكس تاريخ المشروع ومشكلاته بصورة دقيقة.', 'Review project records to ensure they accurately reflect the project history and issues.', false),
  (0, 21, 0, 'إضافة مطورين جدد إلى الفريق خلال هذا التكرار فقط.', 'Add new developers to the team for this iteration only.', false),
  (0, 21, 1, 'العمل لساعات إضافية على المشروع.', 'Work overtime on the project.', false),
  (0, 21, 2, 'الاستمرار في العمل بوتيرة مستدامة وعدم تمديد التكرار.', 'Continue working at a sustainable pace and do not extend the iteration.', true),
  (0, 21, 3, 'تأخير تاريخ انتهاء التكرار.', 'Delay the iteration end date.', false),
  (0, 22, 0, 'مراجعة خطة المشروع لتقييم ما إذا كان ينبغي إجراء أي تحديثات', 'Review the project plan to assess whether any updates are needed.', true),
  (0, 22, 1, 'يقوم بضغط الجدول الحالي بموارد إضافية لتقديم المزيد من الميزات', 'Crash the current schedule by adding resources to deliver more features.', false),
  (0, 22, 2, 'يقوم بإيقاف المشروع على الفور لأن فرصة السوق قد ضاعت بالفعل', 'Immediately stop the project because the market opportunity has already been lost.', false),
  (0, 22, 3, 'الالتزام بخطة المشروع وتاريخ التسليم المستهدف كما هو متوقع', 'Stay committed to the project plan and target delivery date as planned.', false),
  (0, 23, 0, 'مراجعة قائمة المعالم الرئيسية لتحديد المهام التي يمكن تنفيذها بالتوازي (Fast-tracking)', 'Review the milestone list to identify tasks that can be fast-tracked.', false),
  (0, 23, 1, 'مراجعة خطة إدارة المخاطر لتحديد استراتيجية الاستجابة', 'Review the risk management plan to identify a response strategy.', false),
  (0, 23, 2, 'تصعيد المشكلة إلى الراعي واستخلاص المعلومات منه بشأن الموقف', 'Escalate the issue to the sponsor and obtain a briefing on the situation.', false),
  (0, 23, 3, 'تنظيم اجتماع للفريق لمناقشة مسار العمل التالي', 'Organize a team meeting to discuss the next course of action.', true),
  (0, 24, 0, 'يضع قاعدة أساسية للامتثال لمعيار الجودة، ويطلب من أعضاء الفريق تطبيقها.', 'Set a compliance baseline for the quality standard and ask team members to apply it.', false),
  (0, 24, 1, 'يستمر في العملية كما هي، وينتظر حتى المرحلة التالية لاقتراح أي تحسينات.', 'Continue the current process and wait until the next phase to propose improvements.', false),
  (0, 24, 2, 'يناقش تحسين العملية مع مدير مكتب إدارة المشاريع PMO لتحديث إطار عمل تسليم المشروع.', 'Discuss process improvement with the Project Management Office (PMO) to update the project delivery framework.', false),
  (0, 24, 3, 'يفهم سياق العملية والترابطات الموجودة فيها من أعضاء الفريق، ثم يحدد التحسينات المناسبة.', 'Understand the process context and dependencies from the team, then identify appropriate improvements.', true),
  (0, 25, 0, 'الاجتماع مع فريق المشروع لتحليل التكلفة الفعلية لتحديد الانحرافات', 'Meet with the project team to analyze actual costs and identify variances.', true),
  (0, 25, 1, 'يطلب من راعي المشروع المساعدة في إعادة الميزانية إلى مسارها الصحيح', 'Ask the project sponsor for help in bringing the budget back on track.', false),
  (0, 25, 2, 'إصدار طلب تغيير متضمنًا التحليل لزيادة الميزانية', 'Submit a change request that includes an analysis to increase the budget.', false),
  (0, 25, 3, 'إبلاغ المعنيين أن المشروع سينتهي في حدود الميزانية', 'Tell stakeholders that the project will finish within budget.', false),
  (0, 26, 0, 'مراقبة مقاييس الجودة لضمان استمرار المشروع كما هو مخطط له.', 'Monitor quality metrics to ensure the project continues as planned.', false),
  (0, 26, 1, 'أعد تقييم سجل المخاطر للتأكد من تحديثه.', 'Reassess the risk register to ensure it is up to date.', false),
  (0, 26, 2, 'توثيق الدروس المستفادة لضمان عدم حدوث المشكلة مرة أخرى.', 'Document lessons learned to help prevent the issue from recurring.', true),
  (0, 26, 3, 'حدد موعدًا لاجتماع فريق لمراجعة المشكلة.', 'Schedule a team meeting to review the issue.', false),
  (0, 27, 0, 'يشكر عضو الفريق على إثارة هذه المشكلة. وتسجيلها. وينتقل إلى الموضوع التالي.', 'Thank the team member for raising the issue, record it, and move to the next topic.', false),
  (0, 27, 1, 'تصرف بطريقة تسلط الضوء على خطورة الموقف', 'Respond in a way that emphasizes the seriousness of the situation.', false),
  (0, 27, 2, 'تركيز المناقشة على استعادة الأداء وطرق العودة إلى المسار الصحيح', 'Focus the discussion on restoring performance and ways to get back on track.', true),
  (0, 27, 3, 'معاقبة عضو الفريق لتقديمه بيانات سلبية من شأنها التأثير على معنويات الفريق.', 'Punish the team member for presenting negative information that could affect team morale.', false),
  (0, 28, 0, 'تضمين الدروس المستفادة من المشاريع السابقة', 'Include lessons learned from previous projects.', false),
  (0, 28, 1, 'استخدام التقدير من القاعدة إلى القمة', 'Use bottom-up estimating.', true),
  (0, 28, 2, 'التحقق من صحة مؤشر أداء الجدول الزمني لتقييم الانحراف', 'Validate the schedule performance index (SPI) to assess variance.', false),
  (0, 28, 3, 'استخدام التقدير ثلاثي النقاط', 'Use three-point estimating.', false),
  (0, 29, 0, 'الثقة في تقدير المخاطر لفريق التطوير، وإبلاغ راعي المشروع بأن بيانات المخاطر سيتم تقييمها في وقت لاحق.', 'Trust the development team’s risk assessment and tell the sponsor the risk data will be evaluated later.', false),
  (0, 29, 1, 'إنشاء سجل للمخاطر وتضمين خطر عام واحد، واضبط المستوى على منخفض، ثم أغلق المخاطر في نهاية المشروع.', 'Create a risk register with one general risk, set its level to low, and close it at the end of the project.', false),
  (0, 29, 2, 'إنشاء سجل مخاطر لتحديد المخاطر وتسجيلها ومراجعتها وإدارتها باستخدام عملية إدارة المخاطر.', 'Create a risk register to identify, record, review, and manage risks using the risk management process.', true),
  (0, 29, 3, 'تجميع جميع إدخالات سجل أعمال المنتج التي تم تقييمها من قبل فريق التطوير للحصول على دليل على أن إدارة المخاطر قد اكتملت.', 'Compile all product backlog entries assessed by the development team as evidence that risk management is complete.', false),
  (0, 30, 0, 'اسمح لفريق المشروع بمناقشة المشكلة مع عضو الفريق هذا', 'Allow the project team to discuss the issue with the team member.', true),
  (0, 30, 1, 'إبلاغ قسم الموارد البشرية بالموضوع.', 'Inform Human Resources about the matter.', false),
  (0, 30, 2, 'التحدث إلى عضو الفريق بشأن الحاجة إلى تحسين الأداء.', 'Speak with the team member about the need to improve performance.', false),
  (0, 30, 3, 'مناقشة المشكلة مع المدير الوظيفي لعضو الفريق.', 'Discuss the issue with the team member’s functional manager.', false),
  (0, 31, 0, 'توضيح تقدم العمل الحالي وأسباب التأخير والمخاطر الحالية والإجراءات التصحيحية المخطط لها.', 'Clarify current progress, reasons for the delays, current risks, and planned corrective actions.', true),
  (0, 31, 1, 'دراسة شروط العقد والمواعيد النهائية للتأكد من أنها ليست تحت المخاطر وتأكيدها مع المعنيين.', 'Review the contract terms and deadlines to ensure they are not at risk, then confirm them with stakeholders.', false),
  (0, 31, 2, 'اطلب من المعنيين التزام الهدوء والتأكيد على مشاركتهم في اجتماعات الفريق.', 'Ask stakeholders to remain calm and confirm their participation in team meetings.', false),
  (0, 31, 3, 'تقديم طلب للحصول على مزيد من الوقت والميزانية المتعلقة بالتبعية والصعوبات الفنية.', 'Submit a request for additional time and budget related to the dependency and technical difficulties.', false),
  (0, 32, 0, 'يراجع الخيارات والحلول الممكنة مع فريق المشروع.', 'Review possible options and solutions with the project team.', true),
  (0, 32, 1, 'يطلب تمديد مدة المشروع لتسليم النطاق المتفق عليه.', 'Request an extension to deliver the agreed scope.', false),
  (0, 32, 2, 'يطلب دعمًا لزيادة قدرة الفريق على إنجاز العمل في الوقت المحدد.', 'Request support to increase the team’s capacity to complete the work on time.', false),
  (0, 32, 3, 'يحدث سجل المشكلات ويصعد المشكلة إلى راعي المشروع.', 'Update the issue log and escalate the issue to the project sponsor.', false),
  (0, 33, 0, 'زيادة النسبة المخصصة لاختبار كل عنصر في سجل أعمال المنتج.', 'Increase the proportion of time allocated to testing each product backlog item.', false),
  (0, 33, 1, 'تنظيم مراجعات سبرنت بصورة أكثر تكرارًا وبمشاركة جمهور أوسع.', 'Hold sprint reviews more frequently and involve a broader audience.', false),
  (0, 33, 2, 'إنشاء فريق مستقل لضمان الجودة بعيدًا عن فريق التطوير.', 'Create an independent quality assurance team separate from the development team.', false),
  (0, 33, 3, 'إعداد قالب أكثر شمولًا لتعريف الإنجاز (Definition of Done - DoD).', 'Develop a more comprehensive Definition of Done (DoD) template.', true),
  (0, 34, 0, 'مطالبة الفريق بالبدء في المخرج الأسهل أولًا حتى يكتسب الخبرة اللازمة لتنفيذ المخرج الثاني.', 'Ask the team to start with the easier deliverable so they can gain experience before working on the second.', false),
  (0, 34, 1, 'مطالبة فريق المشروع بتنفيذ كلا المخرجين في الوقت نفسه؛ لأن ذلك مطلوب ومعتمد في ميثاق المشروع.', 'Ask the team to work on both deliverables simultaneously because this is required and approved in the project charter.', false),
  (0, 34, 2, 'مطالبة المعنيين الرئيسيين بإلغاء المشروع بسبب صعوبة تنفيذ المخرجين في الوقت نفسه.', 'Ask key stakeholders to cancel the project because delivering both at the same time is difficult.', false),
  (0, 34, 3, 'الاجتماع مع راعي المشروع والمعنيين الرئيسيين لتقييم قيمة كل مخرج للمؤسسة وتحديد أولويات التنفيذ.', 'Meet with the project sponsor and key stakeholders to assess the organizational value of each deliverable and prioritize the work.', true),
  (0, 35, 0, 'التحقق من صحة المعلومات وتحديث خطة إدارة المخاطر.', 'Validate the information and update the risk management plan.', false),
  (0, 35, 1, 'استخدام معدات مستعملة من أجل الاستعداد لأي تأخير في التسليم.', 'Use used equipment to prepare for any delivery delay.', false),
  (0, 35, 2, 'إبلاغ الراعي بالمشكلة المحتملة واطلب أي اقتراحات', 'Inform the sponsor about the potential issue and ask for suggestions.', false),
  (0, 35, 3, 'تحديث سجل المخاطر ومناقشته مع المعنيين في المشروع.', 'Update the risk register and discuss it with project stakeholders.', true),
  (0, 36, 0, 'تخصيص وقت إضافي لفحص جودة الشحنات عند وصولها إلى الموقع.', 'Allow additional time to inspect the quality of shipments when they arrive at the site.', false),
  (0, 36, 1, 'مراجعة متطلبات العقد وطلب الأدلة المناسبة التي تثبت تطبيق ضمان الجودة.', 'Review the contract requirements and request appropriate evidence that quality assurance is being applied.', true),
  (0, 36, 2, 'مطالبة المورد بإصدار وثائق الجودة قبل عملية التسليم التالية', 'Ask the supplier to issue quality documents before the next delivery.', false),
  (0, 36, 3, 'الاتصال بالمورد والحصول منه على ضمان شفهي بشأن جودة عملية التسليم التالية في الموقع.', 'Call the supplier and obtain a verbal assurance about the quality of the next delivery to the site.', false),
  (0, 37, 0, 'ضمان توقع المعني للعقبات التي تحول دون تحقيق الإغلاق المالي على الأموال المتبقية.', 'Ensure that stakeholders anticipated obstacles to achieving financial close for the remaining funds.', false),
  (0, 37, 1, 'التأكد من استمرار اهتمام المعني الذي سيقدم الأموال الإضافية بالمشروع.', 'Ensure that the stakeholder providing the additional funds remained interested in the project.', false),
  (0, 37, 2, 'ضمان تقييم المخاطر على نحو ملائم والتخفيف منها من قبل المعنيين المناسبين.', 'Ensure that risks were appropriately assessed and mitigated by the relevant stakeholders.', true),
  (0, 37, 3, 'ضمان قيام فريق المشروع بمتابعة ومراجعة سجل المخاطر للمشروع دوريًا.', 'Ensure that the project team regularly monitored and reviewed the project risk register.', false),
  (0, 38, 0, 'مراجعة هيكل تجزئة العمل مع الموردين', 'Review the work breakdown structure with the suppliers.', false),
  (0, 38, 1, 'مناقشة إشكالات المسار الحرج مع قسم المشتريات', 'Discuss the critical-path issues with the procurement department.', true),
  (0, 38, 2, 'مراجعة المسار الحرج مع المعنيين لتحديد الخطوات التالية.', 'Review the critical path with stakeholders to determine next steps.', false),
  (0, 38, 3, 'تصعيد الإشكالات المتعلقة بالمورد للراعي من أجل إيجاد حل', 'Escalate supplier issues to the sponsor for resolution.', false),
  (0, 39, 0, 'مراجعة أصول عمليات المؤسسة وإجراء تقدير تناظري.', 'Review organizational process assets and perform analogous estimating.', true),
  (0, 39, 1, 'طلب موارد إضافية ومراجعة تقدير المشروع.', 'Request additional resources and review the project estimate.', false),
  (0, 39, 2, 'إجراء التقدير من أسفل إلى أعلى لأنشطة المشروع.', 'Perform bottom-up estimating for project activities.', false),
  (0, 39, 3, 'تسجيل خطر جديد في خطة إدارة المخاطر.', 'Record a new risk in the risk management plan.', false),
  (0, 40, 0, 'مطالبة المعنيين الرئيسيين بترتيب التقارير حسب الأولوية بناءً على أهداف العمل.', 'Ask key stakeholders to prioritize the reports based on business objectives.', false),
  (0, 40, 1, 'تطوير ميزات جديدة بناءً على تقارير العملاء.', 'Develop new features based on customer reports.', true),
  (0, 40, 2, 'تنقيح سجل الأعمال وترتيب أولوياته بالاستناد إلى التقارير.', 'Refine and prioritize the backlog based on the reports.', true),
  (0, 40, 3, 'مراجعة التقارير للتأكد من أنها قابلة للجمع بسهولة.', 'Review the reports to ensure they can be aggregated easily.', false),
  (0, 40, 4, 'التحقق من صحة التقارير للتأكد من دقتها مع مجموعة فرعية من العملاء.', 'Validate the reports for accuracy with a subset of customers.', false),
  (0, 41, 0, 'تحديد الحد الأدنى من الوظائف المطلوبة في المنتج.', 'Identify the minimum functionality required in the product.', true),
  (0, 41, 1, 'زيادة مستوى التفاصيل في هيكل تقسيم العمل (WBS) لتقليل الأخطاء والتأخيرات.', 'Increase the detail in the work breakdown structure (WBS) to reduce errors and delays.', false),
  (0, 41, 2, 'تقسيم سجل المنتج (Backlog) إلى مراحل لضمان تسليم الخصائص الرئيسية أولًا.', 'Divide the product backlog into phases to ensure key features are delivered first.', false),
  (0, 41, 3, 'طلب من الراعي (Sponsor) أن يحدد أولويات بعض وظائف المنتج.', 'Ask the sponsor to prioritize some product functions.', false),
  (0, 42, 0, 'تفكيك المتطلبات وتحديد أولوياتها في حزم عمل تكرارية (Iterative Work Packages).', 'Decompose and prioritize the requirements into iterative work packages.', true),
  (0, 42, 1, 'تجاهل المتطلبات غير الواضحة والتركيز فقط على خطة تسليم المشروع.', 'Ignore the unclear requirements and focus only on the project delivery plan.', false),
  (0, 42, 2, 'تصعيد مشكلة المتطلبات غير الواضحة إلى فريق الإدارة والانتظار للحصول على الموافقة النهائية.', 'Escalate the unclear requirements to management and wait for final approval.', false),
  (0, 42, 3, 'الانتظار حتى تصبح المتطلبات أكثر وضوحًا قبل اتخاذ أي إجراء آخر في المشروع.', 'Wait until the requirements become clearer before taking any other project action.', false),
  (0, 43, 0, 'تصعيد المشكلة إلى راعي المشروع.', 'Escalate the issue to the project sponsor.', false),
  (0, 43, 1, 'بدء طلب تغيير لتمديد التاريخ النهائي للمشروع', 'Submit a change request to extend the project end date.', false),
  (0, 43, 2, 'تمديد المواعيد الخاصة بالمعالم المستقبلية للمشروع', 'Extend the dates of future project milestones.', false),
  (0, 43, 3, 'معالجة المشكلة خلال اجتماع تخطيط السبرنت القادم.', 'Address the problem during the next sprint planning meeting.', true),
  (0, 44, 0, 'تقديم الإرشاد والتوجيه (Mentoring) لقائد الفريق الجديد.', 'Mentor and coach the new team lead.', true),
  (0, 44, 1, 'إدارة فريق المشروع مباشرةً لتجنب التأخيرات.', 'Manage the project team directly to avoid delays.', false),
  (0, 44, 2, 'إبلاغ راعي المشروع بالتأخير المحتمل.', 'Inform the project sponsor about the potential delay.', false),
  (0, 44, 3, 'طلب من مدير الموارد البشرية تعيين قائد فريق ذي خبرة أعلى.', 'Ask Human Resources to appoint a more experienced team lead.', false),
  (0, 45, 0, 'التنبؤي (Predictive)', 'Predictive', false),
  (0, 45, 1, 'التكراري (Iterative)', 'Iterative', false),
  (0, 45, 2, 'التزايدي (Incremental)', 'Incremental', false),
  (0, 45, 3, 'الرشيق (Agile)', 'Agile', true),
  (0, 46, 0, 'طلب من قسم الموارد البشرية (HR) إرسال أعضاء الفريق إلى ورشة عمل لإدارة التغيير.', 'Ask Human Resources to send team members to a change-management workshop.', false),
  (0, 46, 1, 'طلب استبدال أعضاء الفريق الذين لا يعجبهم هذا الأسلوب في العمل.', 'Request replacement of team members who dislike this way of working.', false),
  (0, 46, 2, 'جدولة جلسة مع مالك المنتج لشرح أنه لا يمكن إضافة مهام الدعم إلى السبرنتات من الآن فصاعدًا.', 'Schedule a session with the product owner to explain that support tasks can no longer be added to sprints.', false),
  (0, 46, 3, 'جدولة جلسة مع الفريق لمناقشة المشكلات والعمل معهم على وضع خطة لإدارة السبرنتات مستقبلًا.', 'Schedule a team session to discuss the issues and collaboratively develop a plan for managing future sprints.', true),
  (0, 47, 0, 'طلب من مكتب إدارة المشاريع (PMO) تعيين مورد مخصص لمراقبة البيئة الخارجية لتمكين وقت أكبر للاستجابة.', 'Ask the Project Management Office (PMO) to assign a dedicated resource to monitor the external environment and allow more response time.', false),
  (0, 47, 1, 'تقييم عواقب عدم الامتثال مع المعنيين وتحديث سجل المخاطر بالإجراءات المتفق عليها.', 'Assess the consequences of noncompliance with stakeholders and update the risk register with agreed actions.', true),
  (0, 47, 2, 'إيقاف المشروع حتى يتمكن شخص ما داخل المؤسسة من تحديد جميع المتطلبات الجديدة وكيفية تأثيرها على المشروع.', 'Stop the project until someone in the organization determines all new requirements and their impact on the project.', false),
  (0, 47, 3, 'الاتفاق مع فريق المشروع على تطبيق المتطلبات الجديدة في المشروع القادم وليس المشروع الحالي.', 'Agree with the project team to apply the new requirements to the next project rather than the current one.', false),
  (0, 48, 0, 'إنشاء احتياطي إداري للتعامل مع المخاطر غير المعروفة عند حدوثها', 'Establish a management reserve to address unknown risks if they occur.', false),
  (0, 48, 1, 'يجتمع مع المعنيين لإبلاغهم بميزانية الجدول الزمني وتأثير التكلفة في حالة حدوث تأخير في المشروع.', 'Meet with stakeholders to inform them about schedule, budget, and cost impacts if the project is delayed.', false),
  (0, 48, 2, 'تحديد مخاطر المشروع ومعايير النجاح اللازمة.', 'Identify project risks and the required success criteria.', true),
  (0, 48, 3, 'تطبيق أنشطة بناء الفريق', 'Conduct team-building activities.', false),
  (0, 49, 0, 'قيد', 'A constraint.', true),
  (0, 49, 1, 'افتراض', 'An assumption.', false),
  (0, 49, 2, 'الاحتياطي الإداري', 'A management reserve.', false);
INSERT INTO new_choices (exam_no, question_index, position, text_ar, text_en, is_correct) VALUES
  (0, 49, 3, 'تاريخ انتهاء المشروع', 'The project end date.', false),
  (0, 50, 0, 'تصعيد المشكلة إلى سلطة اعلى', 'Escalate the issue to a higher authority.', true),
  (0, 50, 1, 'مناقشة المشكلة في الاجتماع القادم للفريق', 'Discuss the issue at the next team meeting.', false),
  (0, 50, 2, 'تكليف أحد أعضاء الفريق الرئيسيين لمهمة مختلفة', 'Assign one of the key team members to a different task.', false),
  (0, 50, 3, 'حذف الاثنين من الفريق', 'Remove both team members from the team.', false),
  (0, 51, 0, 'تقديم توضيحات خلال اجتماع الدروس المستفادة القادمة حول كيفية عمل المكون.', 'Clarify how the component works during the next lessons-learned meeting.', false),
  (0, 51, 1, 'جدولة اجتماع لتخطيط التكرار مع المهندسين والمصممين لإجراء تعديلات على مخططات المبنى', 'Schedule an iteration planning meeting with the engineers and designers to revise the building drawings.', false),
  (0, 51, 2, 'تيسير جلسة تعاونية بين المهندسين والمصممين لفهم وظيفة المكون بشكل أفضل', 'Facilitate a collaborative session between the engineers and designers to better understand the component’s function.', true),
  (0, 51, 3, 'البحث في المتطلبات التنظيمية المتعلقة بالمكون وعرض النتائج في مراجعة التكرار القادمة', 'Research regulatory requirements related to the component and present the findings at the next iteration review.', false),
  (0, 52, 0, 'الإبقاء على خطة إشراك المعنيين الحالية وتأجيل أي تغييرات حتى مراجعة بوابة المرحلة (Phase Gate) التالية.', 'Maintain the current stakeholder engagement plan and defer changes until the next phase-gate review.', false),
  (0, 52, 1, 'إعادة تقييم مستوى الإلحاح، وتحديث خطط التقييم وإشراك المعنيين، وتعديل أولويات التسليم ذات الصلة.', 'Reassess urgency, update assessment and stakeholder engagement plans, and adjust related delivery priorities.', true),
  (0, 52, 2, 'إضافة احتياطيات مخاطر إضافية إلى الميزانية لتعويض الغرامات المحتملة الناتجة عن عدم الالتزام بالموعد النهائي.', 'Add more risk reserves to the budget to cover potential penalties for missing the deadline.', false),
  (0, 52, 3, 'تكليف محلل الامتثال بالمسؤولية المباشرة عن إدارة التواصل مع الجهة التنظيمية.', 'Assign the compliance analyst direct responsibility for managing communication with the regulator.', false),
  (0, 53, 0, 'التفاوض على تعديل العقود لتوضيح بروتوكولات التواصل وصلاحيات اتخاذ القرار.', 'Negotiate contract amendments to clarify communication protocols and decision-making authority.', false),
  (0, 53, 1, 'تطبيق إطار حوكمة يحدد الأدوار والمسؤوليات وحدود التواصل.', 'Implement a governance framework that defines roles, responsibilities, and communication boundaries.', true),
  (0, 53, 2, 'وضع بروتوكولات واضحة للتواصل وتوعية العميل بقنوات التواصل الصحيحة.', 'Establish clear communication protocols and educate the client about the correct communication channels.', false),
  (0, 53, 3, 'جدولة جلسات منتظمة بين العميل والفريق مع جدول أعمال منظم للمناقشات الفنية.', 'Schedule regular sessions between the client and team with structured agendas for technical discussions.', false),
  (0, 54, 0, 'إجراء تحليل للمعنيين وتعزيز رؤية المشروع من خلال استراتيجيات إشراكهم.', 'Analyze stakeholders and reinforce the project vision through engagement strategies.', true),
  (0, 54, 1, 'تنظيم جلسات لإدارة المخاطر لتوثيق المخاطر الناتجة عن اختلافات المعنيين.', 'Conduct risk-management sessions to document risks caused by stakeholder differences.', false),
  (0, 54, 2, 'تيسير جلسات تنقيح سجل المنتج (Product Backlog Refinement) لإظهار كيف تدعم التغييرات أهداف المشروع.', 'Facilitate product backlog refinement sessions to show how changes support project objectives.', false),
  (0, 54, 3, 'طلب من راعي المشروع تقديم عرض للمعنيين لتوضيح رؤية المشروع وتقليل المقاومة.', 'Ask the project sponsor to present the vision to stakeholders and reduce resistance.', false),
  (0, 55, 0, 'تذكير المعنيين بالتزامهم تجاه المشروع وحثهم على الاستجابة بشكل أكبر لتحديثات التقدم.', 'Remind stakeholders of their project commitments and urge them to respond more to progress updates.', false),
  (0, 55, 1, 'تغيير شكل التحديثات المرسلة لجميع المعنيين من تقارير تفصيلية إلى رسومات جذابة حتى لا يتم تجاهلها', 'Change all stakeholder updates from detailed reports to attractive graphics so they will not be ignored.', false),
  (0, 55, 2, 'الاستمرار في إرسال تحديثات التقدم بنفس الطريقة طالما أن المشروع يسير بسلاسة ولا توجد مشكلات.', 'Continue sending updates the same way as long as the project is running smoothly and there are no issues.', false),
  (0, 55, 3, 'تعديل استراتيجية إشراك المعنيين بما يتناسب مع ظروفهم. من خلال التواصل بوتيرة مختلفة أو باستخدام أساليب تواصل مختلفة.', 'Adapt the stakeholder engagement strategy to their circumstances by changing communication frequency or methods.', true),
  (0, 56, 0, 'مراجعة المسؤوليات الفردية لمنع حدوث أي ارتباك داخل فريق التنفيذ.', 'Review individual responsibilities to prevent confusion within the delivery team.', false),
  (0, 56, 1, 'توثيق المشكلة ثم تحديث سجل التغييرات وسجل المشكلات.', 'Document the issue and then update the change log and issue log.', false),
  (0, 56, 2, 'إبلاغ الفريق بالمشكلة والاستمرار في تنفيذ جدول الإصدارات الحالي.', 'Inform the team about the issue and continue with the current release schedule.', false),
  (0, 56, 3, 'جمع ملاحظات المعنيين ومناقشتها مع الفريق للحصول على فهم أفضل للمشكلة.', 'Gather stakeholder feedback and discuss it with the team to better understand the problem.', true),
  (0, 57, 0, 'التأكد من أن جميع وثائق المشروع الموجودة في مستودع المعرفة محدثة ويسهل الوصول إليها.', 'Ensure all existing project documents in the knowledge repository are up to date and easy to access.', false),
  (0, 57, 1, 'عقد جلسات عصف ذهني لمناقشة أفكار جميع أعضاء الفريق حول المشروع.', 'Hold brainstorming sessions to discuss all team members’ ideas about the project.', false),
  (0, 57, 2, 'إضافة وقت إلى الجدول الزمني لمراعاة فترة تعلم أعضاء الفريق الجدد.', 'Add time to the schedule to account for the new team members’ learning period.', false),
  (0, 57, 3, 'تيسير محادثات متكررة وإنشاء علاقات توجيه (Mentoring) بين أعضاء الفريق القدامى والجدد.', 'Facilitate recurring conversations and establish mentoring relationships between experienced and new team members.', true),
  (0, 58, 0, 'إعادة تصنيف هذا المعني لتعديل استراتيجية إشراكه.', 'Reclassify the stakeholder and adjust the engagement strategy.', true),
  (0, 58, 1, 'الحد من مشاركة هذا المعني لتجنب المزيد من التشتيت.', 'Limit the stakeholder’s participation to avoid further distraction.', false),
  (0, 58, 2, 'تسجيل هذه الحالة في سجل المشكلات (Issue Log) ومتابعتها حتى يتم حلها.', 'Record the situation in the issue log and monitor it until resolved.', false),
  (0, 58, 3, 'تصعيد الزيادة غير المتوقعة في مشاركة هذا المعني إلى راعي المشروع.', 'Escalate the unexpected increase in stakeholder engagement to the project sponsor.', false),
  (0, 59, 0, 'زيادة عدد اجتماعات الفريق لمناقشة جميع الاستفسارات.', 'Increase the number of team meetings to discuss all questions.', false),
  (0, 59, 1, 'العمل بشكل مستقل حتى يحين وقت دمج الأعمال', 'Work independently until it is time to integrate the work.', false),
  (0, 59, 2, 'مراجعة خطة إدارة التواصل وزيادة مشاركة المعلومات.', 'Review the communications management plan and increase information sharing.', true),
  (0, 59, 3, 'رفع الأسئلة إلى المديرين الوظيفيين لحل المشكلات بين أعضاء الفريق.', 'Refer questions to functional managers to resolve issues between team members.', false),
  (0, 60, 0, 'تحديث إطار الامتثال موضحًا الإجراءات اللازمة للوفاء بالمتطلبات التنظيمية في ظل وضع الموارد الجديد.', 'Update the compliance framework to explain the steps required to meet regulatory requirements under the new resource situation.', false),
  (0, 60, 1, 'الحفاظ على الجدول الزمني الأصلي. والتواصل والتعاون مع المعنيين لتخفيف المخاطر والالتزام بالمتطلبات التنظيمية.', 'Maintain the original schedule and collaborate with stakeholders to mitigate risks and meet regulatory requirements.', true),
  (0, 60, 2, 'إعطاء الأولوية للمهام التي تساعد على تسريع الجدول الزمني. وتأجيل المهام المتعلقة بالامتثال التنظيمي.', 'Prioritize tasks that accelerate the schedule and defer regulatory compliance tasks.', false),
  (0, 60, 3, 'تعيين متعاقدين مؤقتين لسد النقص في الموارد وتحفيزهم على الالتزام بالجدول الزمني المعجل.', 'Hire temporary contractors to fill the resource gap and motivate them to meet the accelerated schedule.', false),
  (0, 61, 0, 'تيسير عملية ترتيب الأولويات مع المعنيين باستخدام معايير أعمال متفق عليها قبل اعتماد خط أساس النطاق.', 'Facilitate prioritization with stakeholders using agreed business criteria before approving the scope baseline.', true),
  (0, 61, 1, 'الموافقة على طلب مسؤول العمليات لأن ضمان استقرار البنية التحتية يمنع الأعطال ويحافظ على الجودة.', 'Approve the operations manager’s request because infrastructure stability prevents failures and maintains quality.', false),
  (0, 61, 2, 'الموافقة على طلب مدير التسويق لأن تقديم خصائص مرئية للعملاء يحقق نتائج سريعة ويزيد من دعم المعنيين.', 'Approve the marketing manager’s request because visible customer features deliver quick results and stakeholder support.', false),
  (0, 61, 3, 'طلب تمويل إضافي مع توضيح أن إطلاق الخصائص مبكرًا سيزيد من رضا العملاء.', 'Request additional funding, explaining that early feature releases will increase customer satisfaction.', false),
  (0, 62, 0, 'تقليل الاختبارات ونطاق المشروع فورًا لخفض التكاليف. حتى لو أدى ذلك إلى تقليل المنافع', 'Immediately reduce testing and project scope to lower costs, even if benefits are reduced.', false),
  (0, 62, 1, 'إعداد خطة تصحيحية بالتعاون مع المعنيين. وإعادة اعتماد خط الأساس رسميًا. مع الحفاظ على المنافع الأساسية للمشروع.', 'Develop a corrective action plan with stakeholders and formally rebaseline while preserving the project’s core benefits.', true),
  (0, 62, 2, 'توضيح جميع منافع المشروع والإشارة إلى أنه يمكن تقليل النطاق دون تأثير يُذكر.', 'Explain all project benefits and say that scope can be reduced with little impact.', false),
  (0, 62, 3, 'تأجيل الإبلاغ عن تجاوز التكاليف لأن من المتوقع تحقيق وفورات في المراحل اللاحقة من المشروع', 'Delay reporting the cost overrun because savings are expected in later phases.', false),
  (0, 63, 0, 'تقليل نطاق المشروع فورًا لتقليل الاعتماد على المورد والبحث عن وسائل لتقليل التعامل معه.', 'Immediately reduce project scope to reduce dependency on the supplier and find ways to limit dealings with it.', false),
  (0, 63, 1, 'الاجتماع مع المورد للتأكد من صحة المعلومات ومناقشة الخيارات المتاحة لتجنب الإفلاس.', 'Meet with the supplier to verify the information and discuss options to avoid bankruptcy.', false),
  (0, 63, 2, 'الاستمرار مع المورد الحالي على أمل أن يتحسن وضعه المالي قبل أن تتأثر عمليات التسليم.', 'Continue with the current supplier and hope its financial position improves before deliveries are affected.', false),
  (0, 63, 3, 'تفعيل خطة الطوارئ بالتعاون مع مسؤول المشتريات والبحث عن موردين بديلين.', 'Activate the contingency plan with procurement and identify alternative suppliers.', true),
  (0, 64, 0, 'التأكد من أن المشروع القادم سيكون أصغر وأقل تعقيدًا لزيادة فرص نجاحه.', 'Ensure the next project is smaller and less complex to increase its chances of success.', false),
  (0, 64, 1, 'استطلاع آراء المعنيين حول أسباب فشل المشروع ومشاركة النتائج مع الفريق.', 'Survey stakeholders about the reasons for failure and share the findings with the team.', false),
  (0, 64, 2, 'إجراء تحليل ما بعد انتهاء المشروع وتوثيق النتائج للاستفادة منها في تحسين المشاريع المستقبلية.', 'Conduct a post-project analysis and document the findings to improve future projects.', true),
  (0, 64, 3, 'إجراء تحليل السبب الجذري لتحديد المسؤول عن الفشل وإعادة توزيع الموارد على مشاريع مشابهة.', 'Conduct a root-cause analysis to identify who was responsible for the failure and reassign resources to similar projects.', false),
  (0, 65, 0, 'تطبيق استراتيجية تعتمد على إجراء عمليات تدقيق جودة متكررة وتتبع العيوب لاكتشاف مشكلات الجودة ومعالجتها', 'Use a strategy of frequent quality audits and defect tracking to identify and address quality problems.', false),
  (0, 65, 1, 'إعطاء الأولوية لإطلاق المنتج بسرعة. ثم تحليل ملاحظات العملاء لتحديد التحسينات المطلوبة في الجودة.', 'Prioritize rapid product launch, then analyze customer feedback to identify quality improvements.', false),
  (0, 65, 2, 'تبسيط إجراءات الجودة والامتثال من خلال إسناد مسؤولية مراقبة الجودة إلى عضو محدد في الفريق.', 'Simplify quality and compliance procedures by assigning quality monitoring responsibility to one team member.', false),
  (0, 65, 3, 'وضع مؤشرات جودة وأهداف واضحة لكل مرحلة من مراحل المشروع لضمان الالتزام بمعايير الجودة التنظيمية.', 'Establish clear quality metrics and objectives for each project phase to ensure compliance with regulatory standards.', true),
  (0, 66, 0, 'الرجوع إلى خطة إدارة التواصل لمعرفة من يجب إبلاغه ومتى يتم ذلك.', 'Refer to the communications management plan to determine whom to inform and when.', true),
  (0, 66, 1, 'عدم الإبلاغ عن المشكلة المحتملة حتى تتوفر أدلة كافية تستدعي التدخل.', 'Do not report the potential problem until sufficient evidence is available to warrant intervention.', false),
  (0, 66, 2, 'إبلاغ جميع المعنيين بالمشكلة المحتملة حتى يشاركوا في حلها بسرعة.', 'Inform all stakeholders about the potential problem so they can help resolve it quickly.', false),
  (0, 66, 3, 'دراسة المشكلة وتقديم حلول لأعضاء الفريق المسؤولين عن هذا الجزء من المشروع.', 'Study the problem and present solutions to the team members responsible for this part of the project.', false),
  (0, 67, 0, 'إعداد خطة إدارة المشروع التي تدمج جميع الخطط الفرعية في خطة متكاملة للتنفيذ.', 'Develop the project management plan, integrating all subsidiary plans into an execution plan.', false),
  (0, 67, 1, 'إعداد خطة إدارة الجودة لتوثيق معايير الجودة والإجراءات والأدوار الخاصة بضمان الجودة.', 'Develop the quality management plan to document quality standards, procedures, and quality assurance roles.', false),
  (0, 67, 2, 'عقد اجتماع في بداية المشروع لإعداد سجل المعنيين بهدف دعم إدارة المعنيين وخطة التواصل.', 'Hold a project kickoff meeting to develop the stakeholder register and support stakeholder and communications planning.', false),
  (0, 67, 3, 'إعداد هيكل تجزئة العمل (WBS) لتحديد نطاق المشروع وتنظيم أنشطته.', 'Develop the work breakdown structure (WBS) to define the project scope and organize its activities.', true),
  (0, 68, 0, 'أتمتة عملية الامتثال لتقليل الأخطاء البشرية وزيادة كفاءة إدارة الامتثال.', 'Automate the compliance process to reduce human error and improve efficiency.', false),
  (0, 68, 1, 'تصميم حل مؤقت. ثم تعديل الممارسات في التكرار القادم لتتوافق مع المعيار الجديد', 'Design a temporary solution, then modify practices in the next iteration to comply with the new standard.', false),
  (0, 68, 2, 'إعداد وتنفيذ برامج تدريبية لتوعية العاملين بمتطلبات الامتثال وأفضل الممارسات', 'Develop and deliver training to inform staff about compliance requirements and best practices.', false),
  (0, 68, 3, 'معالجة المتطلب من خلال إجراءات التحكم المتكامل في التغيير مع تحليل أثره على التكلفة والجدول الزمني والامتثال.', 'Address the requirement through integrated change control, analyzing its cost, schedule, and compliance impacts.', true),
  (0, 69, 0, 'تطبيق بند العقد الذي يُلزم المورد بتوفير الأشخاص المحددين. والمطالبة باتخاذ إجراء فوري لتصحيح الوضع.', 'Enforce the contractual clause requiring the supplier to provide the named personnel and request immediate corrective action.', true),
  (0, 69, 1, 'قبول قرار المورد وتحديث خطة إدارة المخاطر للحفاظ على العلاقة الجيدة معه.', 'Accept the supplier’s decision and update the risk management plan to maintain a good relationship.', false),
  (0, 69, 2, 'تكليف موارد داخلية مؤقتًا لسد النقص. وإلزام المورد بتدريبهم.', 'Temporarily assign internal resources to fill the gap and require the supplier to train them.', false),
  (0, 69, 3, 'التفاوض مع المورد لتقليل مدة غياب أصحاب الخبرة عن المشروع.', 'Negotiate with the supplier to shorten the absence of the experienced personnel from the project.', false),
  (0, 70, 0, 'تقييم المنافع النوعية والكمية للمشروع مع مراعاة مدى توافقها مع الأهداف الاستراتيجية للمؤسسة.', 'Assess qualitative and quantitative project benefits and their alignment with the organization’s strategic objectives.', true),
  (0, 70, 1, 'إجراء تحليل مالي بعد انتهاء المشروع لتقييم ما إذا كانت المنافع المالية المتوقعة قد تحققت.', 'Conduct a post-project financial analysis to determine whether expected financial benefits were achieved.', false),
  (0, 70, 2, 'مقارنة النتائج الفعلية للمشروع بالميزانية الأصلية لتقييم الأداء المالي للمشروع.', 'Compare actual project results with the original budget to assess financial performance.', false),
  (0, 70, 3, 'حساب المنافع الملموسة وقسمتها على إجمالي تكاليف المشروع لقياس العائد على الاستثمار (ROI).', 'Calculate tangible benefits and divide them by total project costs to measure return on investment (ROI).', false),
  (0, 71, 0, 'مراجعة العقود الحالية وإجراءات التصعيد مع المورد لمعرفة خيارات الحل.', 'Review current contracts and supplier escalation procedures to identify resolution options.', false),
  (0, 71, 1, 'البحث فورًا عن موردين بديلين لتوفير المواد والمكونات المطلوبة.', 'Immediately look for alternative suppliers to provide the required materials and components.', false),
  (0, 71, 2, 'إجراء تحليل أثر على الجدول الزمني والميزانية والجودة لفهم التأثير الكامل للمشكلة.', 'Conduct an impact analysis of the schedule, budget, and quality to understand the full effect of the problem.', true),
  (0, 71, 3, 'تحديث سجل المخاطر وتطبيق خطط الطوارئ الخاصة بتأخير الموردين', 'Update the risk register and implement contingency plans for supplier delays.', false),
